-- Helper: UIStroke on frame border only (must exist before color picker)
local function MakeStroke(parent, color, thickness)
    local s = Instance.new("UIStroke")
    s.Name = "Stroke"
    s.Color = color or Color3.fromRGB(0,0,0)
    s.Thickness = thickness or 1
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    s.Parent = parent
    return s
end
-- ═══════ CLIPBOARD ═════
local function CopyToClipboard(text)
    if setclipboard then setclipboard(text) return true end
    if pcall(function() game:SetClipboard(text) end) then return true end
    return false
end
-- ══════════════════════════════════════════════
--   SKELETON ESP — R6 only (Drawing API)
-- ══════════════════════════════════════════════
local R6_BONES = {
    {"Head", "Torso"},
    {"Torso", "Left Arm"},
    {"Torso", "Right Arm"},
    -- Continue each arm from its centre to its lower end.
    {"Left Arm", "Left Arm", "LowerEnd"},
    {"Right Arm", "Right Arm", "LowerEnd"},
    {"Torso", "Left Leg"},
    {"Torso", "Right Leg"},
}
local SkeletonObjects = {}
local function IsR6Character(char)
    return char and char:FindFirstChild("Torso") and not char:FindFirstChild("UpperTorso")
end
local function RemoveSkeleton(player)
    local sk = SkeletonObjects[player]
    if not sk then return end
    if sk.Conn then pcall(function() sk.Conn:Disconnect() end) end
    for _, line in ipairs(sk.Lines) do
        pcall(function() line:Remove() end)
    end
    SkeletonObjects[player] = nil
end
local function RemoveAllSkeletons()
    for player, _ in pairs(SkeletonObjects) do
        RemoveSkeleton(player)
    end
end
local function AddSkeleton(player)
    if not ESPConfig.Skeleton then return end
    if not player or player == LocalPlayer then return end
    if SkeletonObjects[player] then return end
    local sk = {Player = player, Lines = {}, Conn = nil}
    for _ = 1, #R6_BONES do
        local line = Drawing.new("Line")
        line.Visible = false
        line.Thickness = 1.5
        line.Color = ESPColors.Skeleton
        line.Transparency = 1
        table.insert(sk.Lines, line)
    end
    sk.Conn = RunService.RenderStepped:Connect(function()
        if not ScriptAlive or not ESPConfig.Skeleton then
            for _, line in ipairs(sk.Lines) do line.Visible = false end
            return
        end
        local char = player.Character
        if not char or not IsR6Character(char) then
            for _, line in ipairs(sk.Lines) do line.Visible = false end
            return
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then
            for _, line in ipairs(sk.Lines) do line.Visible = false end
            return
        end
        local cam = workspace.CurrentCamera
        local col = IsCheatFriend(player)
            and Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
            or ESPColors.Skeleton
        for i, bone in ipairs(R6_BONES) do
            local p0 = char:FindFirstChild(bone[1])
            local p1 = char:FindFirstChild(bone[2])
            local line = sk.Lines[i]
            if p0 and p1 then
                local point0 = p0.Position
                local point1 = p1.Position
                if bone[3] == "LowerEnd" then
                    -- Use the actual lower end of the arm, respecting its rotation.
                    point1 = p1.Position - p1.CFrame.UpVector * (p1.Size.Y * 0.5)
                end
                local v0, on0 = cam:WorldToViewportPoint(point0)
                local v1, on1 = cam:WorldToViewportPoint(point1)
                if on0 and on1 then
                    line.From = Vector2.new(v0.X, v0.Y)
                    line.To = Vector2.new(v1.X, v1.Y)
                    line.Color = col
                    line.Visible = true
                else
                    line.Visible = false
                end
            else
                line.Visible = false
            end
        end
    end)
    SkeletonObjects[player] = sk
end
local function UpdateAllSkeletons()
    if ESPConfig.Skeleton then
        for _, player in next, Players:GetPlayers() do
            AddSkeleton(player)
        end
    else
        RemoveAllSkeletons()
    end
end
-- ══════════════════════════════════════════════
--   ITEM ESP — ProximityPrompt and ClickDetector objects
-- ══════════════════════════════════════════════
ItemESPObjects = {}
ItemESPAddedConn = nil
ItemESPRefreshConn = nil
function GetPromptAdornee(prompt)
    local parent = prompt and prompt.Parent
    if not parent then return nil end
    if parent:IsA("Attachment") then parent = parent.Parent end
    if parent and parent:IsA("BasePart") then return parent end
    if parent and parent:IsA("Model") then
        return parent.PrimaryPart or parent:FindFirstChildWhichIsA("BasePart", true)
    end
    return parent and parent:FindFirstAncestorWhichIsA("BasePart") or nil
end
function RemoveItemESP(prompt)
    local data = ItemESPObjects[prompt]
    if data then
        if data.Gui then data.Gui:Destroy() end
        if data.DistanceGui then data.DistanceGui:Destroy() end
        if data.Highlight then data.Highlight:Destroy() end
    end
    ItemESPObjects[prompt] = nil
end
function RefreshItemESPData(prompt, data)
    local options = ESPConfig.ItemESPOptions or {Charms=true, Distance=true, Name=true}
    local promptEnabled = not prompt:IsA("ProximityPrompt") or prompt.Enabled
    local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
    local exactDistance = root and (root.Position - data.Adornee.Position).Magnitude or math.huge
    local objectName = prompt:IsA("ProximityPrompt") and prompt.ObjectText ~= "" and prompt.ObjectText or data.Adornee.Name
    local action = prompt:IsA("ProximityPrompt") and prompt.ActionText ~= "" and prompt.ActionText or (prompt:IsA("ClickDetector") and "Click" or "Interact")
    data.Label.Text = objectName .. "  [" .. action .. "]"
    data.Label.TextColor3 = C.Accent
    data.DistanceLabel.Text = tostring(math.floor(exactDistance == math.huge and 0 or exactDistance)) .. " studs"
    data.DistanceLabel.TextColor3 = C.Accent
    data.Gui.Enabled = promptEnabled and options.Name
    data.DistanceGui.Enabled = promptEnabled and options.Distance
    data.Highlight.Enabled = promptEnabled and options.Charms and exactDistance <= 3000
    data.Highlight.FillColor = C.Accent
    data.Highlight.OutlineColor = C.Accent
end
function AddItemESP(prompt)
    if not ESPConfig.ItemESP or not prompt or (not prompt:IsA("ProximityPrompt") and not prompt:IsA("ClickDetector")) then return end
    if ItemESPObjects[prompt] then return end
    local adornee = GetPromptAdornee(prompt)
    if not adornee then return end
    local gui = Instance.new("BillboardGui")
    gui.Name = "ApexItemESP"
    gui.Adornee = adornee
    gui.Size = UDim2.new(0, 190, 0, 44)
    gui.StudsOffset = Vector3.new(0, math.max(1.5, adornee.Size.Y * 0.5 + 0.5), 0)
    gui.AlwaysOnTop = true
    gui.MaxDistance = 3000
    gui.Parent = CoreGui
    local label = Instance.new("TextLabel")
    label.Size = UDim2.new(1, 0, 1, 0)
    label.BackgroundTransparency = 1
    label.TextColor3 = C.Accent
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0.25
    label.Font = Enum.Font.GothamBold
    label.TextSize = 12
    label.TextWrapped = true
    label.Parent = gui
    -- Distance has its own billboard below the model.
    local distanceGui = Instance.new("BillboardGui")
    distanceGui.Name = "ApexItemDistanceESP"
    distanceGui.Adornee = adornee
    distanceGui.Size = UDim2.new(0, 150, 0, 24)
    distanceGui.StudsOffset = Vector3.new(0, -math.max(1.5, adornee.Size.Y * 0.5 + 0.5), 0)
    distanceGui.AlwaysOnTop = true
    distanceGui.MaxDistance = 3000
    distanceGui.Parent = CoreGui
    local distanceLabel = Instance.new("TextLabel")
    distanceLabel.Size = UDim2.new(1, 0, 1, 0)
    distanceLabel.BackgroundTransparency = 1
    distanceLabel.TextColor3 = C.Accent
    distanceLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    distanceLabel.TextStrokeTransparency = 0.25
    distanceLabel.Font = Enum.Font.GothamBold
    distanceLabel.TextSize = 11
    distanceLabel.Parent = distanceGui
    local highlight = Instance.new("Highlight")
    highlight.Name = "ApexItemCharm"
    highlight.Adornee = adornee.Parent:IsA("Model") and adornee.Parent or adornee
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency = 0.78
    highlight.OutlineTransparency = 0.15
    highlight.Parent = CoreGui
    local data = {Gui=gui, Label=label, DistanceGui=distanceGui, DistanceLabel=distanceLabel, Highlight=highlight, Adornee=adornee}
    ItemESPObjects[prompt] = data
    RefreshItemESPData(prompt, data)
end
function StopItemESP()
    if ItemESPAddedConn then ItemESPAddedConn:Disconnect(); ItemESPAddedConn = nil end
    if ItemESPRefreshConn then ItemESPRefreshConn:Disconnect(); ItemESPRefreshConn = nil end
    for prompt in pairs(ItemESPObjects) do RemoveItemESP(prompt) end
end
function StartItemESP()
    StopItemESP()
    ESPConfig.ItemESP = true
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then AddItemESP(object) end
    end
    ItemESPAddedConn = workspace.DescendantAdded:Connect(function(object)
        if ESPConfig.ItemESP and (object:IsA("ProximityPrompt") or object:IsA("ClickDetector")) then task.defer(AddItemESP, object) end
    end)
    local elapsed = 0
    ItemESPRefreshConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not ESPConfig.ItemESP then return end
        elapsed = elapsed + dt
        if elapsed < 1 then return end
        elapsed = 0
        for prompt, data in pairs(ItemESPObjects) do
            if not prompt.Parent then
                RemoveItemESP(prompt)
            elseif data.Gui and data.Highlight and data.Adornee then
                RefreshItemESPData(prompt, data)
            end
        end
        for _, object in ipairs(workspace:GetDescendants()) do
            if (object:IsA("ProximityPrompt") or object:IsA("ClickDetector")) and not ItemESPObjects[object] then AddItemESP(object) end
        end
    end)
end
-- ══════════════════════════════════════════════
--   FLY (CFrame + velocity zero)
-- ══════════════════════════════════════════════
local V3_ZERO = Vector3.new(0, 0, 0)
local FlyConn1, FlyConn2 = nil, nil
local function StopFly()
    if FlyConn1 then FlyConn1:Disconnect(); FlyConn1 = nil end
    if FlyConn2 then FlyConn2:Disconnect(); FlyConn2 = nil end
    local Char = LocalPlayer.Character
    if Char then
        local Root = Char:FindFirstChild("HumanoidRootPart")
        if Root then
            pcall(function() Root.AssemblyLinearVelocity = V3_ZERO end)
            pcall(function() Root.AssemblyAngularVelocity = V3_ZERO end)
        end
        local Hum = Char:FindFirstChildOfClass("Humanoid")
        if Hum then Hum.PlatformStand = false end
    end
end
local function StartFly()
    StopFly()
    FlyConn1 = RunService.Stepped:Connect(function()
        if not ScriptAlive or not Config.FlyEnabled then StopFly(); return end
        local Char = LocalPlayer.Character
        if not Char then return end
        for _, part in pairs(Char:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function()
                    part.Velocity = V3_ZERO
                    part.RotVelocity = V3_ZERO
                    part.AssemblyLinearVelocity = V3_ZERO
                    part.AssemblyAngularVelocity = V3_ZERO
                end)
            end
        end
    end)
    FlyConn2 = RunService.RenderStepped:Connect(function()
        if not ScriptAlive or not Config.FlyEnabled then StopFly(); return end
        local Char = LocalPlayer.Character
        if not Char then return end
        local Root = Char:FindFirstChild("HumanoidRootPart")
        if not Root then return end
        pcall(function() Root:SetNetworkOwner(LocalPlayer) end)
        local camCF = workspace.CurrentCamera.CFrame
        local moveDir = V3_ZERO
        if UIS:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + camCF.LookVector end
        if UIS:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - camCF.LookVector end
        if UIS:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - camCF.RightVector end
        if UIS:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + camCF.RightVector end
        if UIS:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end
        if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then moveDir = moveDir - Vector3.new(0, 1, 0) end
        if moveDir.Magnitude > 0 then
            Root.CFrame = Root.CFrame + moveDir.Unit * Config.FlySpeed * 0.016
        end
        for _, part in pairs(Char:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function()
                    part.Velocity = V3_ZERO
                    part.RotVelocity = V3_ZERO
                    part.AssemblyLinearVelocity = V3_ZERO
                    part.AssemblyAngularVelocity = V3_ZERO
                end)
            end
        end
    end)
end
table.insert(Connections, LocalPlayer.CharacterAdded:Connect(function()
    if Config.FlyEnabled then
        task.wait(0.3)
        StartFly()
    end
end))
-- ══════════════════════════════════════════════
--   BLINK NOCLIP
--   Server: character stays anchored in place
--   Local:  ghost part inside Camera (not replicated) moves freely
--   Camera: CameraSubject = ghost → mouse rotation still works normally
--   On disable: Root.CFrame = ghost position (the "blink")
-- ══════════════════════════════════════════════
local BlinkGhost = nil  -- BasePart inside workspace.CurrentCamera (client-only)
local function StopBlink()
    Config.NoclipEnabled = false
    local Char = LocalPlayer.Character
    if Char then
        local Root = Char:FindFirstChild("HumanoidRootPart")
        if Root and BlinkGhost then
            -- Blink: teleport real character to where ghost is
            Root.Anchored = false
            Root.CFrame = CFrame.new(BlinkGhost.Position)
        elseif Root then
            Root.Anchored = false
        end
        -- Restore camera subject to the humanoid
        local Hum = Char:FindFirstChildOfClass("Humanoid")
        if Hum then workspace.CurrentCamera.CameraSubject = Hum end
    end
    if BlinkGhost then BlinkGhost:Destroy(); BlinkGhost = nil end
end
local function StartBlink()
    StopBlink()  -- clean up any previous state first
    local Char = LocalPlayer.Character
    if not Char then return end
    local Root = Char:FindFirstChild("HumanoidRootPart")
    if not Root then return end
    Config.NoclipEnabled = true
    -- Freeze the real character — server sees it staying in place
    Root.Anchored = true
    -- Ghost part: parented to Camera → stays client-side, never replicates to server
    local ghost = Instance.new("Part")
    ghost.Name        = "BlinkGhost"
    ghost.Size        = Vector3.new(2, 2, 1)
    ghost.CFrame      = Root.CFrame
    ghost.Anchored    = true
    ghost.CanCollide  = false
    ghost.Transparency = 1
    ghost.Parent      = workspace.CurrentCamera
    BlinkGhost = ghost
    -- Camera follows ghost; player still rotates view with mouse (Custom mode)
    workspace.CurrentCamera.CameraSubject = ghost
end
-- Ghost movement loop — runs every frame when blink is active
table.insert(Connections, RunService.Heartbeat:Connect(function(dt)
    if not ScriptAlive or not Config.NoclipEnabled then return end
    if not BlinkGhost or not BlinkGhost.Parent then
        StopBlink(); return
    end
    local cam = workspace.CurrentCamera
    local dir = Vector3.new(0, 0, 0)
    if UIS:IsKeyDown(Enum.KeyCode.W)         then dir = dir + cam.CFrame.LookVector  end
    if UIS:IsKeyDown(Enum.KeyCode.S)         then dir = dir - cam.CFrame.LookVector  end
    if UIS:IsKeyDown(Enum.KeyCode.A)         then dir = dir - cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.D)         then dir = dir + cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.Space)     then dir = dir + Vector3.new(0, 1, 0)   end
    if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.new(0, 1, 0)   end
    if dir.Magnitude > 0 then dir = dir.Unit end
    BlinkGhost.CFrame = CFrame.new(BlinkGhost.Position + dir * Config.NoclipSpeed * dt)
end))
-- ══════════════════════════════════════════════
--   COLOR PICKER  (circular hue wheel + brightness)
-- ══════════════════════════════════════════════
local ActivePicker = nil
local function OpenColorPicker(key, swatchBtn, screenGui, anchorFrame)
    if ActivePicker then ActivePicker:Destroy(); ActivePicker = nil end
    local curColor = ESPColors[key]
    local R = math.floor(curColor.R * 255)
    local G = math.floor(curColor.G * 255)
    local B = math.floor(curColor.B * 255)
    local POP_W, POP_H = 260, 320
    local ap = anchorFrame.AbsolutePosition
    local asz = anchorFrame.AbsoluteSize
    local popX = math.clamp(ap.X + asz.X/2 - POP_W/2, 8, workspace.CurrentCamera.ViewportSize.X - POP_W - 8)
    local popY = math.clamp(ap.Y + asz.Y/2 - POP_H/2, 8, workspace.CurrentCamera.ViewportSize.Y - POP_H - 8)
    local root = Instance.new("Frame")
    root.Name = "ColorPickerRoot"
    root.Size = UDim2.new(1, 0, 1, 0)
    root.BackgroundTransparency = 1
    root.ZIndex = 100
    root.Parent = screenGui
    local isDraggingAny = false
    local backdrop = Instance.new("TextButton")
    backdrop.Size = UDim2.new(1, 0, 1, 0)
    backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    backdrop.BackgroundTransparency = 0.55
    backdrop.BorderSizePixel = 0
    backdrop.Text = ""
    backdrop.AutoButtonColor = false
    backdrop.ZIndex = 100
    backdrop.Parent = root
    backdrop.MouseButton1Click:Connect(function()
        if not isDraggingAny then
            root:Destroy(); ActivePicker = nil
        end
    end)
    local pop = Instance.new("Frame")
    pop.Size = UDim2.new(0, POP_W, 0, POP_H)
    pop.Position = UDim2.new(0, popX, 0, popY)
    pop.BackgroundColor3 = C.BG
    pop.BorderSizePixel = 0
    pop.ZIndex = 101
    pop.Parent = root
    Instance.new("UICorner", pop).CornerRadius = UDim.new(0, 12)
    MakeStroke(pop, C.Accent, 1)
    ActivePicker = root
    -- Title
    local titleL = Instance.new("TextLabel")
    titleL.Text = "Color: " .. key
    titleL.Size = UDim2.new(1, -36, 0, 22)
    titleL.Position = UDim2.new(0, 10, 0, 8)
    titleL.BackgroundTransparency = 1
    titleL.TextColor3 = C.TMain
    titleL.Font = Enum.Font.GothamBold
    titleL.TextSize = 13
    titleL.TextXAlignment = Enum.TextXAlignment.Left
    titleL.TextStrokeTransparency = 1
    titleL.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    titleL.ZIndex = 102
    titleL.Parent = pop
    -- Close button
    local closeB = Instance.new("TextButton")
    closeB.Text = "X"
    closeB.Size = UDim2.new(0, 22, 0, 22)
    closeB.Position = UDim2.new(1, -28, 0, 7)
    closeB.BackgroundColor3 = C.Card
    closeB.BorderSizePixel = 0
    closeB.AutoButtonColor = false
    closeB.Font = Enum.Font.GothamBold
    closeB.TextSize = 12
    closeB.TextColor3 = C.TDim
    closeB.TextStrokeTransparency = 1
    closeB.ZIndex = 102
    closeB.Parent = pop
    Instance.new("UICorner", closeB).CornerRadius = UDim.new(0, 6)
    closeB.MouseButton1Click:Connect(function() root:Destroy(); ActivePicker = nil end)
    -- Preview circle
    local prev = Instance.new("Frame")
    prev.Size = UDim2.new(0, 40, 0, 40)
    prev.AnchorPoint = Vector2.new(0.5, 0)
    prev.Position = UDim2.new(0.5, 0, 0, 38)
    prev.BackgroundColor3 = ESPColors[key]
    prev.BorderSizePixel = 0
    prev.ZIndex = 102
    prev.Parent = pop
    Instance.new("UICorner", prev).CornerRadius = UDim.new(1, 0)
    MakeStroke(prev, C.Border, 1.5)
    local function RefreshPreview()
        prev.BackgroundColor3 = Color3.fromRGB(R, G, B)
    end
    RefreshPreview()
    -- Helper: make one RGB slider row
    local sliderConns = {}
    local function MakeRGBSlider(label, colorFn, getValue, setValue, yPos)
        local lbl = Instance.new("TextLabel")
        lbl.Text = label
        lbl.Size = UDim2.new(0, 20, 0, 14)
        lbl.Position = UDim2.new(0, 10, 0, yPos)
        lbl.BackgroundTransparency = 1
        lbl.TextColor3 = C.TDim
        lbl.Font = Enum.Font.GothamBold
        lbl.TextSize = 11
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.TextStrokeTransparency = 1
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.ZIndex = 102
        lbl.Parent = pop
        local valLbl = Instance.new("TextLabel")
        valLbl.Text = tostring(getValue())
        valLbl.Size = UDim2.new(0, 28, 0, 14)
        valLbl.Position = UDim2.new(1, -38, 0, yPos)
        valLbl.BackgroundTransparency = 1
        valLbl.TextColor3 = C.TMain
        valLbl.Font = Enum.Font.GothamBold
        valLbl.TextSize = 11
        valLbl.TextXAlignment = Enum.TextXAlignment.Right
        valLbl.TextStrokeTransparency = 1
        valLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        valLbl.ZIndex = 102
        valLbl.Parent = pop
        local trackY = yPos + 18
        local track = Instance.new("TextButton")
        track.Size = UDim2.new(1, -20, 0, 14)
        track.Position = UDim2.new(0, 10, 0, trackY)
        track.BackgroundColor3 = C.Track
        track.BorderSizePixel = 0
        track.AutoButtonColor = false
        track.Text = ""
        track.ZIndex = 102
        track.Parent = pop
        Instance.new("UICorner", track).CornerRadius = UDim.new(0, 7)
        local fill = Instance.new("Frame")
        fill.Size = UDim2.new(getValue() / 255, 0, 1, 0)
        fill.BackgroundColor3 = colorFn()
        fill.BorderSizePixel = 0
        fill.ZIndex = 103
        fill.Parent = track
        Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 7)
        local knob = Instance.new("Frame")
        knob.Size = UDim2.new(0, 16, 0, 16)
        knob.Position = UDim2.new(getValue() / 255, -8, 0.5, -8)
        knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        knob.BorderSizePixel = 0
        knob.ZIndex = 104
        knob.Parent = track
        Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
        local dragging = false
        local function UpdateSlider(inputX)
            local t = math.clamp((inputX - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
            local v = math.floor(t * 255)
            setValue(v)
            fill.Size = UDim2.new(t, 0, 1, 0)
            fill.BackgroundColor3 = colorFn()
            knob.Position = UDim2.new(t, -8, 0.5, -8)
            valLbl.Text = tostring(v)
            RefreshPreview()
        end
        track.MouseButton1Down:Connect(function()
            dragging = true
            isDraggingAny = true
            local pos = UIS:GetMouseLocation()
            UpdateSlider(pos.X)
        end)
        local c1 = UIS.InputChanged:Connect(function(i)
            if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
                UpdateSlider(i.Position.X)
            end
        end)
        local c2 = UIS.InputEnded:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = false
                task.defer(function() isDraggingAny = false end)
            end
        end)
        table.insert(sliderConns, c1)
        table.insert(sliderConns, c2)
    end
    MakeRGBSlider("R", function() return Color3.fromRGB(R, 0, 0) end,
        function() return R end, function(v) R = v end, 100)
    MakeRGBSlider("G", function() return Color3.fromRGB(0, G, 0) end,
        function() return G end, function(v) G = v end, 170)
    MakeRGBSlider("B", function() return Color3.fromRGB(0, 0, B) end,
        function() return B end, function(v) B = v end, 240)
    -- Apply button
    local applyB = Instance.new("TextButton")
    applyB.Text = "Apply"
    applyB.Size = UDim2.new(1, -20, 0, 30)
    applyB.Position = UDim2.new(0, 10, 0, 278)
    applyB.BackgroundColor3 = C.Accent
    applyB.BorderSizePixel = 0
    applyB.TextColor3 = C.BG
    applyB.Font = Enum.Font.GothamBold
    applyB.TextSize = 13
    applyB.TextStrokeTransparency = 1
    applyB.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    applyB.ZIndex = 102
    applyB.Parent = pop
    Instance.new("UICorner", applyB).CornerRadius = UDim.new(0, 8)
    applyB.MouseButton1Click:Connect(function()
        ESPColors[key] = Color3.fromRGB(R, G, B)
        swatchBtn.BackgroundColor3 = ESPColors[key]
        for _, c in ipairs(sliderConns) do c:Disconnect() end
        root:Destroy(); ActivePicker = nil
        UpdateESP()
    end)
end
-- ══════════════════════════════════════════════
--   TIME STOP
-- ══════════════════════════════════════════════
local HitboxConn = nil
local _hbOrigSizes = {}   -- [player] = originalHeadSize (Vector3)
local function StopHitbox()
    Config.HitboxEnabled = false
    if HitboxConn then HitboxConn:Disconnect(); HitboxConn = nil end
    -- Restore original head sizes
    for player, origSize in pairs(_hbOrigSizes) do
        pcall(function()
            local char = player.Character
            if not char then return end
            local head = char:FindFirstChild("Head")
            if head and head:IsA("BasePart") then
                head.Size = origSize
                head.LocalTransparencyModifier = 0
            end
        end)
    end
    _hbOrigSizes = {}
end
local function StartHitbox()
    StopHitbox()
    Config.HitboxEnabled = true
    HitboxConn = RunService.Heartbeat:Connect(function()
        if not ScriptAlive or not Config.HitboxEnabled then
            StopHitbox(); return
        end
        local scale = math.clamp(Config.HitboxSize or 3, 1, 10)
        for _, player in ipairs(Players:GetPlayers()) do
            if player == LocalPlayer then continue end
            pcall(function()
                local char = player.Character
                if not char then return end
                local head = char:FindFirstChild("Head")
                if not head or not head:IsA("BasePart") then return end
                if IsCheatFriend(player) then
                    local original = _hbOrigSizes[player]
                    if original then head.Size = original end
                    head.LocalTransparencyModifier = 0
                    _hbOrigSizes[player] = nil
                    return
                end
                -- Cache original size once per character
                if not _hbOrigSizes[player]
                   or (_hbOrigSizes[player].Magnitude < 0.1) then
                    _hbOrigSizes[player] = head.Size
                end
                local orig = _hbOrigSizes[player]
                head.Size = orig * scale
                -- Keep head invisible locally so it doesn't look odd
                head.LocalTransparencyModifier = 1
            end)
        end
    end)
    -- Clear cache when a player's character is replaced
    for _, player in ipairs(Players:GetPlayers()) do
        if player == LocalPlayer then continue end
        player.CharacterAdded:Connect(function()
            _hbOrigSizes[player] = nil
        end)
    end
    Players.PlayerAdded:Connect(function(player)
        player.CharacterAdded:Connect(function()
            _hbOrigSizes[player] = nil
        end)
    end)
end
-- ══════════════════════════════════════════════
--   FREE CAM
--   Scriptable camera decoupled from character.
--   Mouse rotates view, WASD/Space/Ctrl move it.
--   LeftShift = speed boost (x3).
-- ══════════════════════════════════════════════
local FC_BIND  = "ApexMirageFreeCam"
local FC_CF    = CFrame.new(0, 0, 0)
local FC_PITCH = 0
local FC_YAW   = 0
local FC_RETURN_CAMERA_CF = nil
local FC_RETURN_ROOT_ROTATION = nil
local FC_WAS_ACTIVE = false
local function StopFreeCam()
    local wasActive = FC_WAS_ACTIVE
    local returnCameraCF = FC_RETURN_CAMERA_CF
    local returnRootRotation = FC_RETURN_ROOT_ROTATION
    FC_WAS_ACTIVE = false
    FC_RETURN_CAMERA_CF = nil
    FC_RETURN_ROOT_ROTATION = nil
    Config.FreeCamEnabled = false
    RunService:UnbindFromRenderStep(FC_BIND)
    UIS.MouseBehavior = Enum.MouseBehavior.Default
    local char = LocalPlayer.Character
    if char then
        local root = char:FindFirstChild("HumanoidRootPart")
        if root then
            if wasActive and returnRootRotation then
                root.CFrame = CFrame.new(root.Position) * returnRootRotation
            end
            root.Anchored = false
            root.AssemblyLinearVelocity  = V3_ZERO
            root.AssemblyAngularVelocity = V3_ZERO
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum.PlatformStand = false end
    end
    local cam = workspace.CurrentCamera
    cam.CameraType = Enum.CameraType.Custom
    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if hum then cam.CameraSubject = hum end
    if wasActive and returnCameraCF then
        -- Restore the exact viewing direction from before Free Cam.
        cam.CFrame = returnCameraCF
        task.defer(function()
            if cam and cam.Parent and not Config.FreeCamEnabled then
                cam.CFrame = returnCameraCF
            end
        end)
    end
end
local function StartFreeCam()
    StopFreeCam()
    Config.FreeCamEnabled = true
    local char = LocalPlayer.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    root.Anchored = true
    root.AssemblyLinearVelocity  = V3_ZERO
    root.AssemblyAngularVelocity = V3_ZERO
    if hum then hum.PlatformStand = true end
    local cam = workspace.CurrentCamera
    FC_RETURN_CAMERA_CF = cam.CFrame
    FC_RETURN_ROOT_ROTATION = root.CFrame.Rotation
    FC_WAS_ACTIVE = true
    cam.CameraType = Enum.CameraType.Scriptable
    FC_CF = cam.CFrame
    local lv = cam.CFrame.LookVector
    FC_YAW   = math.deg(math.atan2(-lv.X, -lv.Z))
    FC_PITCH = math.deg(math.asin(math.clamp(lv.Y, -1, 1)))
    UIS.MouseBehavior = Enum.MouseBehavior.LockCenter
    RunService:BindToRenderStep(FC_BIND, Enum.RenderPriority.Camera.Value + 1, function(dt)
        if not ScriptAlive or not Config.FreeCamEnabled then StopFreeCam(); return end
        local ch = LocalPlayer.Character
        if ch then
            local r = ch:FindFirstChild("HumanoidRootPart")
            if r then
                r.Anchored = true
                r.AssemblyLinearVelocity  = V3_ZERO
                r.AssemblyAngularVelocity = V3_ZERO
            end
            local h = ch:FindFirstChildOfClass("Humanoid")
            if h then h.PlatformStand = true end
        end
        local delta = UIS:GetMouseDelta()
        FC_PITCH = math.clamp(FC_PITCH - delta.Y * 0.3, -89, 89)
        FC_YAW   = FC_YAW - delta.X * 0.3
        local orientation = CFrame.Angles(0, math.rad(FC_YAW), 0)
                          * CFrame.Angles(math.rad(FC_PITCH), 0, 0)
        local spd = Config.FreeCamSpeed * dt
        if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then spd = spd * 3 end
        local move = Vector3.new(0, 0, 0)
        if UIS:IsKeyDown(Enum.KeyCode.W) then move = move + orientation.LookVector  end
        if UIS:IsKeyDown(Enum.KeyCode.S) then move = move - orientation.LookVector  end
        if UIS:IsKeyDown(Enum.KeyCode.A) then move = move - orientation.RightVector end
        if UIS:IsKeyDown(Enum.KeyCode.D) then move = move + orientation.RightVector end
        if move.Magnitude > 0 then
            FC_CF = CFrame.new(FC_CF.Position + move.Unit * spd) * orientation
        else
            FC_CF = CFrame.new(FC_CF.Position) * orientation
        end
        workspace.CurrentCamera.CFrame = FC_CF
    end)
end
-- ══════════════════════════════════════════════
--   FORCED LIGHTING OVERRIDES
--   Reapplied every frame so the game cannot overwrite them.
-- ══════════════════════════════════════════════
local OriginalLighting = {
    Brightness = Lighting.Brightness,
    ClockTime = Lighting.ClockTime,
    GlobalShadows = Lighting.GlobalShadows,
    Ambient = Lighting.Ambient,
    OutdoorAmbient = Lighting.OutdoorAmbient,
    ExposureCompensation = Lighting.ExposureCompensation,
    FogStart = Lighting.FogStart,
    FogEnd = Lighting.FogEnd,
}
local OriginalAtmospheres = {}
for _, obj in ipairs(Lighting:GetDescendants()) do
    if obj:IsA("Atmosphere") then
        OriginalAtmospheres[obj] = {Density=obj.Density, Haze=obj.Haze, Glare=obj.Glare}
    end
end
local function RestoreFullbright()
    pcall(function()
        Lighting.Brightness = OriginalLighting.Brightness
        Lighting.ClockTime = OriginalLighting.ClockTime
        Lighting.GlobalShadows = OriginalLighting.GlobalShadows
        Lighting.Ambient = OriginalLighting.Ambient
        Lighting.OutdoorAmbient = OriginalLighting.OutdoorAmbient
        Lighting.ExposureCompensation = OriginalLighting.ExposureCompensation
    end)
end
local function RestoreNoFog()
    pcall(function()
        Lighting.FogStart = OriginalLighting.FogStart
        Lighting.FogEnd = OriginalLighting.FogEnd
    end)
    for atmosphere, values in pairs(OriginalAtmospheres) do
        if atmosphere and atmosphere.Parent then
            pcall(function()
                atmosphere.Density = values.Density
                atmosphere.Haze = values.Haze
                atmosphere.Glare = values.Glare
            end)
        end
    end
end
local function ApplyForcedLighting()
    if Config.FullbrightEnabled then
        Lighting.Brightness = 3
        Lighting.ClockTime = 14
        Lighting.GlobalShadows = false
        Lighting.Ambient = Color3.fromRGB(255, 255, 255)
        Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
        Lighting.ExposureCompensation = 0
    end
    if Config.NoFogEnabled then
        Lighting.FogStart = 0
        Lighting.FogEnd = 1000000
        for _, obj in ipairs(Lighting:GetDescendants()) do
            if obj:IsA("Atmosphere") then
                if not OriginalAtmospheres[obj] then
                    OriginalAtmospheres[obj] = {Density=obj.Density, Haze=obj.Haze, Glare=obj.Glare}
                end
                obj.Density = 0
                obj.Haze = 0
                obj.Glare = 0
            end
        end
    end
end
table.insert(Connections, RunService.RenderStepped:Connect(function()
    if ScriptAlive then ApplyForcedLighting() end
end))
-- ══════════════════════════════════════════════
--   NO CD JUMP
--   Re-enables and requests Jumping continuously to bypass client-side delays.
-- ══════════════════════════════════════════════
local LastForcedJump = 0
local ForcedJumpCapUntil = 0
local function ForceJumpNow()
    if not ScriptAlive or not Config.NoCDJumpEnabled then return end
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 then return end
    -- JumpRequest and Heartbeat may fire in the same frame; block duplicate impulses.
    local now = os.clock()
    if now - LastForcedJump < 0.08 then return end
    if hum.FloorMaterial == Enum.Material.Air then return end
    LastForcedJump = now
    ForcedJumpCapUntil = now + 0.15
    pcall(function()
        hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
        -- Generate every No CD Jump impulse with a fixed force of 42.
        local originalUseJumpPower = hum.UseJumpPower
        local originalJumpPower = hum.JumpPower
        local originalJumpHeight = hum.JumpHeight
        hum.UseJumpPower = true
        hum.JumpPower = 42
        hum.Jump = true
        hum:ChangeState(Enum.HumanoidStateType.Jumping)
        task.defer(function()
            if not hum or not hum.Parent or not root or not root.Parent then return end
            pcall(function()
                -- Clamp the actual vertical launch velocity so duplicate game-side
                -- jump code cannot produce an impulse higher than 42.
                local velocity = root.AssemblyLinearVelocity
                root.AssemblyLinearVelocity = Vector3.new(velocity.X, 42, velocity.Z)
                hum.JumpPower = originalJumpPower
                hum.JumpHeight = originalJumpHeight
                hum.UseJumpPower = originalUseJumpPower
            end)
        end)
    end)
end
table.insert(Connections, UIS.JumpRequest:Connect(ForceJumpNow))
table.insert(Connections, RunService.Heartbeat:Connect(function()
    if not ScriptAlive or not Config.NoCDJumpEnabled then return end
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true) end)
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if root and os.clock() < ForcedJumpCapUntil then
        local velocity = root.AssemblyLinearVelocity
        if velocity.Y > 42 then
            root.AssemblyLinearVelocity = Vector3.new(velocity.X, 42, velocity.Z)
        end
    end
    if UIS:IsKeyDown(Enum.KeyCode.Space) then ForceJumpNow() end
end))
-- ══════════════════════════════════════════════
--   INSTANT INTERACTION
--   Forces every ProximityPrompt hold duration to zero.
-- ══════════════════════════════════════════════
InstantPromptOriginals = setmetatable({}, {__mode = "k"})
InstantPromptAddedConn = nil
InstantPromptEnforceConn = nil
function MakePromptInstant(prompt)
    if not prompt or not prompt:IsA("ProximityPrompt") then return end
    if InstantPromptOriginals[prompt] == nil then
        InstantPromptOriginals[prompt] = prompt.HoldDuration
    end
    prompt.HoldDuration = math.clamp(Config.InteractionDelay or 0.00, 0.00, 1.00)
end
function StopInstantInteraction()
    if InstantPromptAddedConn then InstantPromptAddedConn:Disconnect(); InstantPromptAddedConn = nil end
    if InstantPromptEnforceConn then InstantPromptEnforceConn:Disconnect(); InstantPromptEnforceConn = nil end
    for prompt, originalDuration in pairs(InstantPromptOriginals) do
        if prompt and prompt.Parent then
            pcall(function() prompt.HoldDuration = originalDuration end)
        end
    end
    InstantPromptOriginals = setmetatable({}, {__mode = "k"})
end
function StartInstantInteraction()
    StopInstantInteraction()
    Config.InstantInteractionEnabled = true
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("ProximityPrompt") then MakePromptInstant(object) end
    end
    InstantPromptAddedConn = workspace.DescendantAdded:Connect(function(object)
        if Config.InstantInteractionEnabled and object:IsA("ProximityPrompt") then
            MakePromptInstant(object)
        end
    end)
    local elapsed = 0
    InstantPromptEnforceConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not Config.InstantInteractionEnabled then return end
        elapsed = elapsed + dt
        if elapsed < 0.5 then return end
        elapsed = 0
        for prompt in pairs(InstantPromptOriginals) do
            if prompt and prompt.Parent then
                pcall(function() prompt.HoldDuration = math.clamp(Config.InteractionDelay or 0.00, 0.00, 1.00) end)
            end
        end
    end)
end
-- ══════════════════════════════════════════════
--   NO VOID
--   NaN protection plus clone desync fallback for server-side void checks.
-- ══════════════════════════════════════════════
OriginalFallenPartsDestroyHeight = workspace.FallenPartsDestroyHeight
NoVoidConn = nil
function StopNoVoid()
    if NoVoidConn then NoVoidConn:Disconnect(); NoVoidConn = nil end
    pcall(function() workspace.FallenPartsDestroyHeight = OriginalFallenPartsDestroyHeight end)
end
function StartNoVoid()
    StopNoVoid()
    Config.NoVoidEnabled = true
    -- Infinite Yield-style No Void: NaN disables the standard Roblox
    -- FallenPartsDestroyHeight comparison without moving the character.
    local NaN = 0 / 0
    pcall(function() workspace.FallenPartsDestroyHeight = NaN end)
    local elapsed = 0
    NoVoidConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not Config.NoVoidEnabled then return end
        elapsed = elapsed + dt
        if elapsed >= 0.5 then
            elapsed = 0
            pcall(function() workspace.FallenPartsDestroyHeight = NaN end)
        end
    end)
end
-- ══════════════════════════════════════════════
--   ORBIT — moves the local character around a selected player.
-- ══════════════════════════════════════════════
OrbitConn = nil
OrbitAngle = 0
OrbitCollisionStates = setmetatable({}, {__mode="k"})
function ApplyOrbitNoCollision(character)
    if not character then return end
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if OrbitCollisionStates[part] == nil then OrbitCollisionStates[part] = part.CanCollide end
            part.CanCollide = false
        end
    end
end
function GetOrbitTarget()
    local userId = tonumber(Config.OrbitTargetUserId) or 0
    if userId <= 0 then return nil end
    for _, player in ipairs(Players:GetPlayers()) do
        if player.UserId == userId and player ~= LocalPlayer then return player end
    end
    return nil
end
function StopOrbit()
    if OrbitConn then OrbitConn:Disconnect(); OrbitConn = nil end
    for part, originalCanCollide in pairs(OrbitCollisionStates) do
        if part and part.Parent then part.CanCollide = originalCanCollide end
    end
    OrbitCollisionStates = setmetatable({}, {__mode="k"})
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root then
        root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end
end
function StartOrbit()
    StopOrbit()
    Config.OrbitEnabled = true
    OrbitAngle = 0
    OrbitConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not Config.OrbitEnabled then return end
        local target = GetOrbitTarget()
        local character = LocalPlayer.Character
        ApplyOrbitNoCollision(character)
        local localRoot = character and character:FindFirstChild("HumanoidRootPart")
        local targetRoot = target and target.Character and target.Character:FindFirstChild("HumanoidRootPart")
        if not localRoot or not targetRoot then return end
        local speed = math.clamp(tonumber(Config.OrbitSpeed) or 90, 1, 720)
        local distance = math.clamp(tonumber(Config.OrbitDistance) or 10, 2, 100)
        OrbitAngle = (OrbitAngle + math.rad(speed) * dt) % (math.pi * 2)
        local center = targetRoot.Position
        local position = center + Vector3.new(math.cos(OrbitAngle) * distance, 0, math.sin(OrbitAngle) * distance)
        localRoot.CFrame = CFrame.new(position, center)
        localRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        localRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end)
end
-- ══════════════════════════════════════════════
--   ANTI-FLING — protects the local character from extreme physics impulses.
-- ══════════════════════════════════════════════
AntiFlingConn = nil
AntiFlingSafeCFrame = nil
AntiFlingSaveElapsed = 0
AntiFlingCollisionElapsed = 0
AntiFlingCollisionStates = setmetatable({}, {__mode="k"})
function ApplyAntiFlingCollisions()
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and player.Character then
            for _, part in ipairs(player.Character:GetDescendants()) do
                if part:IsA("BasePart") then
                    if AntiFlingCollisionStates[part] == nil then AntiFlingCollisionStates[part] = part.CanCollide end
                    if part.CanCollide then part.CanCollide = false end
                end
            end
        end
    end
end
function RestoreAntiFlingCollisions()
    for part, originalCanCollide in pairs(AntiFlingCollisionStates) do
        if part and part.Parent then part.CanCollide = originalCanCollide end
    end
    AntiFlingCollisionStates = setmetatable({}, {__mode="k"})
end
function StopAntiFling()
    if AntiFlingConn then AntiFlingConn:Disconnect(); AntiFlingConn = nil end
    RestoreAntiFlingCollisions()
    AntiFlingSafeCFrame = nil
    AntiFlingSaveElapsed = 0
    AntiFlingCollisionElapsed = 0
end
function StartAntiFling()
    StopAntiFling()
    Config.AntiFlingEnabled = true
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root then AntiFlingSafeCFrame = root.CFrame end
    ApplyAntiFlingCollisions()
    AntiFlingConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not Config.AntiFlingEnabled then return end
        -- Character descendant scans are expensive, so refresh collisions once
        -- per second instead of every rendered physics frame.
        AntiFlingCollisionElapsed = AntiFlingCollisionElapsed + dt
        if AntiFlingCollisionElapsed >= 1 then
            AntiFlingCollisionElapsed = 0
            ApplyAntiFlingCollisions()
        end
        local localCharacter = LocalPlayer.Character
        local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
        local humanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
        if not localRoot or not humanoid or humanoid.Health <= 0 then return end
        local linearSpeed = localRoot.AssemblyLinearVelocity.Magnitude
        local angularSpeed = localRoot.AssemblyAngularVelocity.Magnitude
        if (linearSpeed > 140 or angularSpeed > 60) and AntiFlingSafeCFrame then
            localRoot.CFrame = AntiFlingSafeCFrame + Vector3.new(0, 2, 0)
            localRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            localRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            return
        end
        AntiFlingSaveElapsed = AntiFlingSaveElapsed + dt
        if AntiFlingSaveElapsed >= 0.25 then
            AntiFlingSaveElapsed = 0
            if humanoid.FloorMaterial ~= Enum.Material.Air and linearSpeed < 60 and angularSpeed < 20 then
                AntiFlingSafeCFrame = localRoot.CFrame
            end
        end
    end)
end
-- ══════════════════════════════════════════════
--   EMOTE PLAYER
-- ══════════════════════════════════════════════
EmoteTrack = nil
EmoteCharacterConn = nil
EmoteMaintainConn = nil
-- Catalog Emote Animation asset IDs (not /e dance animation IDs).
EmoteAnimationIds = {
    L = 87560149954505,
    Crying = 82218484353408,
}
function StopEmote()
    if EmoteTrack then
        pcall(function() EmoteTrack:Stop(0.2); EmoteTrack:Destroy() end)
        EmoteTrack = nil
    end
    if EmoteCharacterConn then EmoteCharacterConn:Disconnect(); EmoteCharacterConn = nil end
    if EmoteMaintainConn then EmoteMaintainConn:Disconnect(); EmoteMaintainConn = nil end
end
function PlaySelectedEmote(character)
    if EmoteTrack then
        pcall(function() EmoteTrack:Stop(0.15); EmoteTrack:Destroy() end)
        EmoteTrack = nil
    end
    character = character or LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return end
    local emoteId = EmoteAnimationIds[Config.EmoteChoice or "L"]
    if not emoteId then return end
    -- Emote Animation assets must be played through the Humanoid emote API.
    -- Loading their catalog IDs as ordinary AnimationIds produces /e dance fallbacks.
    local callOk, resultA, resultB = pcall(function()
        return humanoid:PlayEmoteAndGetAnimTrackById(emoteId)
    end)
    if not callOk then return end
    local track = nil
    if typeof(resultA) == "Instance" and resultA:IsA("AnimationTrack") then track = resultA end
    if not track and typeof(resultB) == "Instance" and resultB:IsA("AnimationTrack") then track = resultB end
    if not track then return end
    track.Looped = true
    track.Priority = Enum.AnimationPriority.Action4
    EmoteTrack = track
    if not track.IsPlaying then pcall(function() track:Play(0.15, 1, 1) end) end
end
function StartEmote()
    StopEmote()
    Config.EmoteEnabled = true
    PlaySelectedEmote(LocalPlayer.Character)
    EmoteCharacterConn = LocalPlayer.CharacterAdded:Connect(function(character)
        if not Config.EmoteEnabled then return end
        character:WaitForChild("Humanoid", 10)
        task.wait(0.2)
        PlaySelectedEmote(character)
    end)
    local elapsed = 0
    EmoteMaintainConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not Config.EmoteEnabled then return end
        elapsed = elapsed + dt
        if elapsed < 0.5 then return end
        elapsed = 0
        if not EmoteTrack or not EmoteTrack.IsPlaying then
            PlaySelectedEmote(LocalPlayer.Character)
        end
    end)
end
-- ══════════════════════════════════════════════
--   CLONE DESYNC INVISIBILITY
--   Controls a local clone while the server character is held far away.
-- ══════════════════════════════════════════════
InvisOriginalCharacter = nil
InvisCloneCharacter = nil
InvisOriginalRootAnchored = false
InvisHiddenCFrame = nil
InvisConn = nil
InvisAnimTracks = {}
function StopInvisAnimations()
    for _, track in pairs(InvisAnimTracks) do
        pcall(function() track:Stop(0.15); track:Destroy() end)
    end
    InvisAnimTracks = {}
end
function SetupInvisAnimations(humanoid)
    StopInvisAnimations()
    local animator = humanoid:FindFirstChildOfClass("Animator") or Instance.new("Animator", humanoid)
    local r15 = humanoid.RigType == Enum.HumanoidRigType.R15
    local ids = r15 and {
        Idle="rbxassetid://507766666", Walk="rbxassetid://507777826", Run="rbxassetid://507767714",
        Jump="rbxassetid://507765000", Fall="rbxassetid://507767968",
    } or {
        Idle="rbxassetid://180435571", Walk="rbxassetid://180426354", Run="rbxassetid://180426354",
        Jump="rbxassetid://125750702", Fall="rbxassetid://180436148",
    }
    for name, id in pairs(ids) do
        local animation = Instance.new("Animation")
        animation.AnimationId = id
        local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
        animation:Destroy()
        if ok and track then
            track.Looped = true
            track.Priority = name == "Idle" and Enum.AnimationPriority.Idle or Enum.AnimationPriority.Movement
            InvisAnimTracks[name] = track
        end
    end
end
function UpdateInvisAnimation(humanoid, root)
    local horizontalSpeed = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z).Magnitude
    local wanted
    if humanoid.FloorMaterial == Enum.Material.Air then
        wanted = root.AssemblyLinearVelocity.Y > 0.5 and "Jump" or "Fall"
    elseif horizontalSpeed > 12 then
        wanted = "Run"
    elseif horizontalSpeed > 0.5 then
        wanted = "Walk"
    else
        wanted = "Idle"
    end
    for name, track in pairs(InvisAnimTracks) do
        if name == wanted then
            if not track.IsPlaying then track:Play(0.12) end
            if name == "Walk" or name == "Run" then
                track:AdjustSpeed(math.clamp(horizontalSpeed / 14, 0.35, 2.5))
            end
        elseif track.IsPlaying then
            track:Stop(0.12)
        end
    end
end
function StopInvisibility()
    if InvisConn then InvisConn:Disconnect(); InvisConn = nil end
    StopInvisAnimations()
    local original = InvisOriginalCharacter
    local clone = InvisCloneCharacter
    local cloneRoot = clone and clone:FindFirstChild("HumanoidRootPart")
    if original and original.Parent then
        local originalRoot = original:FindFirstChild("HumanoidRootPart")
        if cloneRoot then pcall(function() original:PivotTo(cloneRoot.CFrame) end) end
        if originalRoot then originalRoot.Anchored = InvisOriginalRootAnchored end
        pcall(function() LocalPlayer.Character = original end)
        local humanoid = original:FindFirstChildOfClass("Humanoid")
        if humanoid then workspace.CurrentCamera.CameraSubject = humanoid end
    end
    if clone and clone.Parent then clone:Destroy() end
    InvisOriginalCharacter = nil
    InvisCloneCharacter = nil
    InvisHiddenCFrame = nil
end
function StartInvisibility()
    StopInvisibility()
    local original = LocalPlayer.Character
    local root = original and original:FindFirstChild("HumanoidRootPart")
    local humanoid = original and original:FindFirstChildOfClass("Humanoid")
    if not original or not root or not humanoid or humanoid.Health <= 0 then
        Config.InvisibilityEnabled = false
        return
    end
    original.Archivable = true
    local clone = original:Clone()
    clone.Name = original.Name .. "_LocalClone"
    for _, object in ipairs(clone:GetDescendants()) do
        if object:IsA("Script") then
            object:Destroy()
        elseif object:IsA("LocalScript") then
            if object.Name == "Animate" then
                object.Disabled = false
            else
                object:Destroy()
            end
        end
    end
    clone.Parent = workspace
    clone:PivotTo(original:GetPivot())
    local cloneHumanoid = clone:FindFirstChildOfClass("Humanoid")
    local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
    if not cloneHumanoid or not cloneRoot then
        clone:Destroy()
        Config.InvisibilityEnabled = false
        return
    end
    -- Hide the local clone's overhead name and health UI.
    cloneHumanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    cloneHumanoid.NameDisplayDistance = 0
    cloneHumanoid.HealthDisplayDistance = 0
    local animate = clone:FindFirstChild("Animate")
    if animate and animate:IsA("LocalScript") then animate.Disabled = false end
    SetupInvisAnimations(cloneHumanoid)
    InvisOriginalCharacter = original
    InvisCloneCharacter = clone
    InvisOriginalRootAnchored = root.Anchored
    -- The server character is held 1000 studs above the activation point,
    -- while the locally controlled clone remains at the original position.
    InvisHiddenCFrame = root.CFrame + Vector3.new(0, 1000, 0)
    root.Anchored = true
    root.CFrame = InvisHiddenCFrame
    pcall(function() LocalPlayer.Character = clone end)
    workspace.CurrentCamera.CameraSubject = cloneHumanoid
    Config.InvisibilityEnabled = true
    InvisConn = RunService.Heartbeat:Connect(function()
        if not ScriptAlive or not Config.InvisibilityEnabled then return end
        local realRoot = InvisOriginalCharacter and InvisOriginalCharacter:FindFirstChild("HumanoidRootPart")
        if realRoot and InvisHiddenCFrame then
            realRoot.Anchored = true
            realRoot.CFrame = InvisHiddenCFrame
            realRoot.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            realRoot.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end
        if InvisCloneCharacter and InvisCloneCharacter.Parent then
            local activeHumanoid = InvisCloneCharacter:FindFirstChildOfClass("Humanoid")
            local activeRoot = InvisCloneCharacter:FindFirstChild("HumanoidRootPart")
            if activeHumanoid and activeRoot then
                pcall(function() UpdateInvisAnimation(activeHumanoid, activeRoot) end)
            end
        else
            Config.InvisibilityEnabled = false
            StopInvisibility()
        end
    end)
end
