local CurTab = "ESP"
local function SwitchTab(T)
    if CurTab == T then return end
    CurTab = T
    for I, N in ipairs(TabN) do
        Pages[N].Visible = (N == T)
        local B = TabB[N]
        local S = B:FindFirstChild("Stroke")
        B.BackgroundColor3 = (N == T) and C.Card or C.Sidebar
        B.TextColor3 = (N == T) and C.TOn or C.TDim
        if S then S.Color = (N == T) and C.Accent or C.Border end
    end
end
