function HighlightSearchEntry(object)
    if not object or not object.Parent or not object:IsA("GuiObject") then return end
    local token = (object:GetAttribute("SearchHighlightToken") or 0) + 1
    object:SetAttribute("SearchHighlightToken", token)
    local stroke = object:FindFirstChild("Stroke") or object:FindFirstChildOfClass("UIStroke")
    local temporaryStroke = false
    if not stroke then
        stroke = MakeStroke(object, C.Accent, 2.5)
        stroke.Name = "SearchHighlightStroke"
        temporaryStroke = true
    end
    local oldColor = stroke.Color
    local oldThickness = stroke.Thickness
    local oldTransparency = stroke.Transparency
    stroke.Color = C.Accent
    stroke.Thickness = 2.5
    stroke.Transparency = 0
    local canTintBackground = object.BackgroundTransparency < 1
    local oldBackground = object.BackgroundColor3
    if canTintBackground then
        TweenService:Create(object, TweenInfo.new(0.18), {BackgroundColor3=C.CardHover}):Play()
    end
    task.delay(2, function()
        if not object or not object.Parent or object:GetAttribute("SearchHighlightToken") ~= token then return end
        if temporaryStroke then
            stroke:Destroy()
        elseif stroke and stroke.Parent then
            TweenService:Create(stroke, TweenInfo.new(0.25), {Color=oldColor, Thickness=oldThickness, Transparency=oldTransparency}):Play()
        end
        if canTintBackground then
            TweenService:Create(object, TweenInfo.new(0.25), {BackgroundColor3=oldBackground}):Play()
        end
    end)
end
function OpenSearchEntry(entry)
    local tabName = nil
    for name, page in pairs(Pages) do
        if page == entry.Parent then tabName = name; break end
    end
    if tabName then SwitchTab(tabName) end
    if entry.Parent and entry.Parent:IsA("ScrollingFrame") then
        entry.Parent.CanvasPosition = Vector2.new(0, math.max((entry.Y or 0) - 8, 0))
    end
    task.defer(function() HighlightSearchEntry(entry.Object) end)
    SearchBar.Text = ""
    SearchResultsFrame.Visible = false
end
function RefreshFunctionSearch()
    for _, child in ipairs(SearchResultsFrame:GetChildren()) do
        if child:IsA("TextButton") or child:IsA("TextLabel") then child:Destroy() end
    end
    local query = SearchBar.Text:lower():gsub("^%s+", ""):gsub("%s+$", "")
    if query == "" then
        SearchResultsFrame.Visible = false
        SearchResultsFrame.Size = UDim2.new(1, -116, 0, 0)
        return
    end
    local matches = {}
    for _, entry in ipairs(SearchEntries) do
        if entry.Name:lower():find(query, 1, true) then table.insert(matches, entry) end
    end
    table.sort(matches, function(a,b) return a.Name:lower() < b.Name:lower() end)
    local count = math.min(#matches, 8)
    local height = count > 0 and (count * 30 + 8) or 38
    SearchResultsFrame.Size = UDim2.new(1, -116, 0, height)
    SearchResultsFrame.Visible = true
    if count == 0 then
        local empty = Instance.new("TextLabel")
        empty.Size = UDim2.new(1, -12, 0, 30)
        empty.Position = UDim2.new(0, 6, 0, 4)
        empty.BackgroundTransparency = 1
        empty.Text = "No functions found"
        empty.TextColor3 = C.TDim
        empty.Font = Enum.Font.Gotham
        empty.TextSize = 11
        empty.TextStrokeTransparency = 1
        empty.ZIndex = 81
        empty.Parent = SearchResultsFrame
        return
    end
    for i = 1, count do
        local entry = matches[i]
        local tabName = ""
        for name, page in pairs(Pages) do if page == entry.Parent then tabName = name; break end end
        local button = Instance.new("TextButton")
        button.Size = UDim2.new(1, -8, 0, 27)
        button.Position = UDim2.new(0, 4, 0, 4 + (i-1)*30)
        button.BackgroundColor3 = C.Card
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = entry.Name .. (tabName ~= "" and ("   [" .. tabName .. "]") or "")
        button.TextColor3 = C.TMain
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Font = Enum.Font.GothamBold
        button.TextSize = 10
        button.TextStrokeTransparency = 1
        button.ZIndex = 81
        button.Parent = SearchResultsFrame
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 6)
        local padding = Instance.new("UIPadding")
        padding.PaddingLeft = UDim.new(0, 9)
        padding.Parent = button
        button.MouseButton1Click:Connect(function() OpenSearchEntry(entry) end)
    end
end
SearchBar:GetPropertyChangedSignal("Text"):Connect(RefreshFunctionSearch)
-- ═══════ LOCAL SCRIPT CHAT ═══════
CHAT_API_URL = "https://worker.macanchatworking.workers.dev"
ChatRoom = game.JobId ~= "" and game.JobId or ("place-" .. tostring(game.PlaceId))
ChatSeenIds = {}
ChatOnlineUsers = {}
ChatLastTimestamp = 0
ChatInitialSyncComplete = false
ChatNotificationRoot = nil
ChatMentionFrame = nil
ChatMessagesFrame = nil
ChatInput = nil
ChatStatus = nil
function ChatHttpRequest(method, path, body)
    local url = CHAT_API_URL .. path
    local requestFunction = (syn and syn.request) or http_request or request
    if requestFunction then
        local options = {Url=url, Method=method, Headers={Accept="application/json"}}
        if body then
            options.Headers["Content-Type"] = "application/json"
            options.Body = HttpService:JSONEncode(body)
        end
        local ok, response = pcall(requestFunction, options)
        if ok and response then
            local status = tonumber(response.StatusCode or response.Status) or 0
            local responseBody = response.Body or response.body or ""
            return status, responseBody
        end
    elseif method == "GET" then
        local ok, responseBody = pcall(function() return game:HttpGet(url) end)
        if ok then return 200, responseBody end
    end
    return 0, ""
end
function SetChatStatus(text, isError)
    if not ChatStatus then return end
    ChatStatus.Text = text or ""
    ChatStatus.TextColor3 = isError and C.Red or C.TDim
end
function PlayChatNotificationSound()
    local soundId = CustomHitSound2Asset
    if not soundId then return end
    local sound = Instance.new("Sound")
    sound.Name = "ApexChatNotification"
    sound.SoundId = soundId
    sound.Volume = 0.6
    sound.Parent = workspace
    sound.Ended:Connect(function() sound:Destroy() end)
    pcall(function() sound:Play() end)
    task.delay(5, function() if sound and sound.Parent then sound:Destroy() end end)
end
function EscapeChatRichText(text)
    return tostring(text or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
end
function FormatChatMentions(text)
    local escaped = EscapeChatRichText(text)
    return escaped:gsub("(@[%w_]+)", '<font color="#FFD166"><b>%1</b></font>')
end
function IsLocalChatMention(text)
    local lowered = tostring(text or ""):lower()
    return lowered:find("@" .. LocalPlayer.Name:lower(), 1, true) ~= nil
        or lowered:find("@" .. LocalPlayer.DisplayName:lower(), 1, true) ~= nil
end
function ShowChatNotification(messageData)
    local usernameText = tostring(messageData.username or "Unknown")
    local messageText = tostring(messageData.message or ""):sub(1, 120)
    local mentioned = IsLocalChatMention(messageText)
    if not ChatNotificationRoot or not ChatNotificationRoot.Parent then
        ChatNotificationRoot = Instance.new("Frame")
        ChatNotificationRoot.Name = "ChatNotifications"
        ChatNotificationRoot.Size = UDim2.new(0, 280, 0, 300)
        ChatNotificationRoot.Position = UDim2.new(1, -290, 0, 10)
        ChatNotificationRoot.BackgroundTransparency = 1
        ChatNotificationRoot.ZIndex = 200
        ChatNotificationRoot.Parent = SG
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 6)
        layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = ChatNotificationRoot
    end
    local panel = Instance.new("Frame")
    panel.Size = UDim2.new(1, 0, 0, 56)
    panel.BackgroundColor3 = C.Card
    panel.BackgroundTransparency = 0.05
    panel.BorderSizePixel = 0
    panel.LayoutOrder = -os.time()
    panel.ZIndex = 201
    panel.Parent = ChatNotificationRoot
    Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 8)
    MakeStroke(panel, C.Accent, 1)
    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, -16, 0, 17)
    title.Position = UDim2.new(0, 8, 0, 6)
    title.BackgroundTransparency = 1
    title.Text = mentioned and ("You were mentioned by " .. usernameText) or ("Chat — " .. usernameText)
    title.TextColor3 = mentioned and C.Yellow or C.TOn
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextStrokeTransparency = 1
    title.ZIndex = 202
    title.Parent = panel
    local text = Instance.new("TextLabel")
    text.Size = UDim2.new(1, -16, 0, 25)
    text.Position = UDim2.new(0, 8, 0, 25)
    text.BackgroundTransparency = 1
    text.RichText = true
    text.Text = FormatChatMentions(messageText)
    text.TextColor3 = C.TMain
    text.TextXAlignment = Enum.TextXAlignment.Left
    text.TextWrapped = true
    text.Font = Enum.Font.Gotham
    text.TextSize = 10
    text.TextStrokeTransparency = 1
    text.ZIndex = 202
    text.Parent = panel
    PlayChatNotificationSound()
    task.delay(4, function()
        if not panel or not panel.Parent then return end
        TweenService:Create(panel, TweenInfo.new(0.25), {BackgroundTransparency=1}):Play()
        TweenService:Create(title, TweenInfo.new(0.25), {TextTransparency=1}):Play()
        TweenService:Create(text, TweenInfo.new(0.25), {TextTransparency=1}):Play()
        task.wait(0.27)
        if panel then panel:Destroy() end
    end)
end
function AddChatMessage(messageData, notify)
    local id = tonumber(messageData.id)
    if not id or ChatSeenIds[id] or not ChatMessagesFrame then return end
    ChatSeenIds[id] = true
    ChatLastTimestamp = math.max(ChatLastTimestamp, tonumber(messageData.created_at) or 0)
    local ownMessage = tostring(messageData.user_id) == tostring(LocalPlayer.UserId)
    if notify and not ownMessage then ShowChatNotification(messageData) end
    local row = Instance.new("Frame")
    row.Name = "ChatMessage_" .. id
    row.Size = UDim2.new(1, -8, 0, 44)
    row.BackgroundColor3 = ownMessage and C.CardOn or C.Card
    row.BorderSizePixel = 0
    row.LayoutOrder = id
    row.Parent = ChatMessagesFrame
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 7)
    MakeStroke(row, ownMessage and C.Accent or C.Border, 1)
    local textOffset = ownMessage and 8 or 42
    if not ownMessage then
        local avatar = Instance.new("ImageLabel")
        avatar.Size = UDim2.new(0, 32, 0, 32)
        avatar.Position = UDim2.new(0, 5, 0.5, -16)
        avatar.BackgroundColor3 = C.Track
        avatar.BorderSizePixel = 0
        avatar.Image = ""
        avatar.ScaleType = Enum.ScaleType.Crop
        avatar.Parent = row
        Instance.new("UICorner", avatar).CornerRadius = UDim.new(1, 0)
        MakeStroke(avatar, C.Border, 1)
        local avatarUserId = tonumber(messageData.user_id)
        if avatarUserId then
            task.spawn(function()
                local ok, image = pcall(function()
                    return Players:GetUserThumbnailAsync(
                        avatarUserId,
                        Enum.ThumbnailType.HeadShot,
                        Enum.ThumbnailSize.Size100x100
                    )
                end)
                if ok and avatar and avatar.Parent then avatar.Image = image end
            end)
        end
    end
    local username = Instance.new("TextLabel")
    username.Size = UDim2.new(1, -(textOffset + 6), 0, 14)
    username.Position = UDim2.new(0, textOffset, 0, 4)
    username.BackgroundTransparency = 1
    username.Text = tostring(messageData.username or "Unknown")
    username.TextColor3 = ownMessage and C.TOn or C.TMain
    username.TextXAlignment = Enum.TextXAlignment.Left
    username.Font = Enum.Font.GothamBold
    username.TextSize = 10
    username.TextStrokeTransparency = 1
    username.Parent = row
    local message = Instance.new("TextLabel")
    message.Size = UDim2.new(1, -(textOffset + 6), 0, 20)
    message.Position = UDim2.new(0, textOffset, 0, 19)
    message.BackgroundTransparency = 1
    message.RichText = true
    message.Text = FormatChatMentions(messageData.message)
    message.TextColor3 = C.TMain
    message.TextXAlignment = Enum.TextXAlignment.Left
    message.TextWrapped = true
    message.Font = Enum.Font.Gotham
    message.TextSize = 11
    message.TextStrokeTransparency = 1
    message.Parent = row
    task.defer(function()
        if ChatMessagesFrame then
            ChatMessagesFrame.CanvasPosition = Vector2.new(0, math.max(ChatMessagesFrame.AbsoluteCanvasSize.Y - ChatMessagesFrame.AbsoluteSize.Y, 0))
        end
    end)
end
function PollChatMessages()
    local after = math.max(ChatLastTimestamp - 1, 0)
    local path = "/messages?room=" .. HttpService:UrlEncode(ChatRoom) .. "&after=" .. tostring(after)
    local status, body = ChatHttpRequest("GET", path)
    if status ~= 200 or body == "" then SetChatStatus("Connection error", true); return end
    local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
    if not ok or not decoded or not decoded.ok then SetChatStatus("Invalid API response", true); return end
    local notify = ChatInitialSyncComplete
    for _, messageData in ipairs(decoded.messages or {}) do AddChatMessage(messageData, notify) end
    ChatInitialSyncComplete = true
    SetChatStatus("Room: " .. ChatRoom:sub(1, 18), false)
end
function SendChatMessage()
    if not ChatInput then return end
    local text = ChatInput.Text:gsub("[%c]", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return end
    if #text > 200 then text = text:sub(1, 200) end
    ChatInput.Text = ""
    SetChatStatus("Sending...", false)
    task.spawn(function()
        local status, body = ChatHttpRequest("POST", "/send", {
            room=ChatRoom,
            user_id=tostring(LocalPlayer.UserId),
            username=LocalPlayer.Name,
            message=text,
        })
        if status == 200 then
            SetChatStatus("Sent", false)
            task.wait(0.15)
            PollChatMessages()
        elseif status == 429 then
            SetChatStatus("Wait before sending again", true)
        else
            local errorText = "Send failed"
            local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
            if ok and decoded and decoded.error then errorText = tostring(decoded.error) end
            SetChatStatus(errorText, true)
        end
    end)
end
function SendChatPresence()
    ChatHttpRequest("POST", "/heartbeat", {
        room=ChatRoom,
        user_id=tostring(LocalPlayer.UserId),
        username=LocalPlayer.Name,
    })
end
function PollChatOnlineUsers()
    local path = "/online?room=" .. HttpService:UrlEncode(ChatRoom)
    local status, body = ChatHttpRequest("GET", path)
    if status ~= 200 or body == "" then return end
    local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
    if not ok or not decoded or not decoded.ok then return end
    local online = {}
    for _, userData in ipairs(decoded.users or {}) do
        online[tostring(userData.user_id)] = true
    end
    ChatOnlineUsers = online
    RefreshChatMentionSuggestions()
end
function RefreshChatMentionSuggestions()
    if not ChatInput or not ChatMentionFrame then return end
    for _, child in ipairs(ChatMentionFrame:GetChildren()) do
        if child:IsA("TextButton") then child:Destroy() end
    end
    local partial = ChatInput.Text:match("@([%w_]*)$")
    if partial == nil then ChatMentionFrame.Visible = false; return end
    partial = partial:lower()
    local candidates = {}
    for _, player in ipairs(Players:GetPlayers()) do
        local isScriptOnline = ChatOnlineUsers[tostring(player.UserId)] == true
        if player ~= LocalPlayer and isScriptOnline and player.Name:lower():sub(1, #partial) == partial then
            table.insert(candidates, player)
        end
    end
    table.sort(candidates, function(a,b) return a.Name:lower() < b.Name:lower() end)
    local count = math.min(#candidates, 5)
    if count == 0 then ChatMentionFrame.Visible = false; return end
    local height = count * 28 + 6
    ChatMentionFrame.Size = UDim2.new(1, -74, 0, height)
    ChatMentionFrame.Position = UDim2.new(0, 0, 1, -(58 + height))
    ChatMentionFrame.Visible = true
    for i = 1, count do
        local player = candidates[i]
        local button = Instance.new("TextButton")
        button.Size = UDim2.new(1, -6, 0, 25)
        button.Position = UDim2.new(0, 3, 0, 3 + (i-1)*28)
        button.BackgroundColor3 = C.Card
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = "@" .. player.Name .. "  (" .. player.DisplayName .. ")"
        button.TextColor3 = C.TMain
        button.TextXAlignment = Enum.TextXAlignment.Left
        button.Font = Enum.Font.GothamBold
        button.TextSize = 10
        button.TextStrokeTransparency = 1
        button.ZIndex = 91
        button.Parent = ChatMentionFrame
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 5)
        local pad = Instance.new("UIPadding")
        pad.PaddingLeft = UDim.new(0, 8)
        pad.Parent = button
        button.MouseButton1Click:Connect(function()
            ChatInput.Text = ChatInput.Text:gsub("@[%w_]*$", "@" .. player.Name .. " ")
            ChatInput.CursorPosition = #ChatInput.Text + 1
            ChatMentionFrame.Visible = false
            ChatInput:CaptureFocus()
        end)
    end
end
