ThemeEffectToken = 0
ThemeEffectFrame = nil
RefreshThemesUI = nil
function StartThemeEffect(theme)
    ThemeEffectToken = ThemeEffectToken + 1
    local token = ThemeEffectToken
    if ThemeEffectFrame then ThemeEffectFrame:Destroy() end
    local effect = Instance.new("Frame")
    effect.Name = "ThemeEffect"
    -- Cover the complete window, including the area underneath the tabs.
    effect.Size = UDim2.new(1, 0, 1, 0)
    effect.Position = UDim2.new(0, 0, 0, 0)
    effect.BackgroundTransparency = 1
    effect.ClipsDescendants = true
    effect.ZIndex = 0
    effect.Parent = MF
    ThemeEffectFrame = effect
    task.spawn(function()
        while ScriptAlive and token == ThemeEffectToken do
            if MF.Visible then
                if theme == "Cosmic" then
                    -- Build a four-point star from UI frames so no unsupported
                    -- font glyph can turn into a square/diamond placeholder.
                    local star = Instance.new("Frame")
                    local size = math.random(9, 14) * 1.2
                    local color = math.random() > 0.65 and Color3.fromRGB(115,115,125) or Color3.fromRGB(215,215,220)
                    local alpha = math.random(10,45)/100
                    star.Size = UDim2.new(0, size, 0, size)
                    star.Position = UDim2.new(math.random(), -size/2, math.random(), -size/2)
                    star.BackgroundTransparency = 1
                    star.Rotation = math.random(0, 45)
                    star.ZIndex = 0
                    star.Parent = effect
                    local rays = {}
                    local function AddRay(widthScale, height, rotation)
                        local rayPart = Instance.new("Frame")
                        rayPart.AnchorPoint = Vector2.new(0.5, 0.5)
                        rayPart.Size = UDim2.new(widthScale, 0, 0, height)
                        rayPart.Position = UDim2.new(0.5, 0, 0.5, 0)
                        rayPart.BackgroundColor3 = color
                        rayPart.BackgroundTransparency = alpha
                        rayPart.BorderSizePixel = 0
                        rayPart.Rotation = rotation
                        rayPart.ZIndex = 0
                        rayPart.Parent = star
                        Instance.new("UICorner", rayPart).CornerRadius = UDim.new(1, 0)
                        table.insert(rays, rayPart)
                    end
                    AddRay(1, 1.4, 0)
                    AddRay(1, 1.4, 90)
                    AddRay(0.55, 1, 45)
                    AddRay(0.55, 1, -45)
                    TweenService:Create(star, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, 1, true), {Rotation=star.Rotation+20}):Play()
                    for _, rayPart in ipairs(rays) do
                        TweenService:Create(rayPart, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, 1, true), {BackgroundTransparency=1}):Play()
                    end
                    task.delay(2.5, function() if star then star:Destroy() end end)
                    task.wait(0.11)
                elseif theme == "Sakura" then
                    local petal = Instance.new("TextLabel")
                    petal.Size = UDim2.new(0, 18, 0, 18)
                    petal.AnchorPoint = Vector2.new(0.5, 0.5)
                    -- Start and finish inside the exact top/bottom GUI edges.
                    petal.Position = UDim2.new(math.random(3,97)/100, 0, 0, 10)
                    petal.BackgroundTransparency = 1
                    petal.Text = "✿"
                    petal.TextColor3 = Color3.fromRGB(255,165,196)
                    petal.TextTransparency = math.random(5,35)/100
                    petal.Font = Enum.Font.GothamBold
                    petal.TextSize = math.random(9,15)
                    petal.Rotation = math.random(0,359)
                    petal.ZIndex = 0
                    petal.Parent = effect
                    local duration = math.random(35,60)/10
                    local petalTween = TweenService:Create(petal, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
                        Position=UDim2.new(math.clamp(petal.Position.X.Scale + math.random(-20,20)/100,0.03,0.97),0,1,-10),
                        Rotation=petal.Rotation + math.random(180,540)
                    })
                    petalTween.Completed:Connect(function()
                        if petal and petal.Parent then petal:Destroy() end
                    end)
                    petalTween:Play()
                    -- 1.5x more frequent Sakura petals.
                    task.wait(0.133)
                else
                    -- Spawn a batch each cycle: task.wait cannot run faster than a
                    -- frame, so batching creates an actually dense rainstorm.
                    -- Optimized rain: four drops per batch instead of creating
                    -- dozens of GUI objects every rendered frame.
                    for rainIndex = 1, 4 do
                        local drop = Instance.new("Frame")
                        local startX, startY
                        if rainIndex == 4 then
                            if math.random() > 0.5 then
                                -- Additional coverage across the top header.
                                startX = math.random(4, 92) / 100
                                startY = math.random(2, 12) / 100
                            else
                                -- Additional coverage behind the left-side tabs.
                                startX = math.random(3, 20) / 100
                                startY = math.random(12, 90) / 100
                            end
                        else
                            startX = math.random(4, 80) / 100
                            startY = math.random(2, 92) / 100
                        end
                        -- Thin layered streak with faded ends, similar to real rain.
                        local bright = math.random() > 0.78
                        drop.Size = UDim2.new(0, bright and 2 or 1, 0, math.random(28,65))
                        drop.AnchorPoint = Vector2.new(0.5, 0.5)
                        drop.Position = UDim2.new(startX, 0, startY, 0)
                        drop.BackgroundColor3 = bright and Color3.fromRGB(135,155,170) or Color3.fromRGB(78,100,116)
                        drop.BackgroundTransparency = bright and math.random(35,52)/100 or math.random(55,73)/100
                        drop.BorderSizePixel = 0
                        drop.Rotation = -18 + math.random(-3,3)
                        drop.ZIndex = 0
                        drop.Parent = effect
                        local fade = Instance.new("UIGradient")
                        fade.Rotation = 90
                        fade.Transparency = NumberSequence.new({
                            NumberSequenceKeypoint.new(0, 1),
                            NumberSequenceKeypoint.new(0.15, 0.25),
                            NumberSequenceKeypoint.new(0.72, 0),
                            NumberSequenceKeypoint.new(1, 1),
                        })
                        fade.Parent = drop
                        -- UIStroke glow was intentionally removed: hundreds of
                        -- animated strokes were the main source of FPS loss.
                        -- Follow one parallel diagonal and stop at whichever GUI
                        -- edge is reached first (right or bottom). This prevents
                        -- every streak from converging into the same corner.
                        local bounds = effect.AbsoluteSize
                        local width = math.max(bounds.X, 1)
                        local height = math.max(bounds.Y, 1)
                        local startPX = startX * width
                        local startPY = startY * height
                        local dirX, dirY = 0.42, 1
                        local rightT = math.max(0, (width - 10 - startPX) / dirX)
                        local bottomT = math.max(0, (height - 28 - startPY) / dirY)
                        local travel = math.min(rightT, bottomT)
                        local endX = (startPX + dirX * travel) / width
                        local endY = (startPY + dirY * travel) / height
                        local duration = math.max(0.12, travel / math.random(700, 900))
                        local rainTween = TweenService:Create(drop, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
                            Position=UDim2.new(endX, 0, endY, 0)
                        })
                        rainTween.Completed:Connect(function()
                            -- Remove the drop on the exact frame it reaches an edge.
                            if drop and drop.Parent then drop:Destroy() end
                        end)
                        rainTween:Play()
                    end
                    task.wait(0.03)
                end
            else
                task.wait(0.2)
            end
        end
    end)
end
function ApplyTheme(theme)
    local palette = ThemePalettes[theme]
    if not palette then return end
    if LogoImage and ThemeLogoImages[theme] then
        LogoImage.Image = ThemeLogoImages[theme]
    end
    -- Rain logo uses a black backing instead of the light-blue theme accent.
    Logo.BackgroundColor3 = theme == "Rain" and Color3.fromRGB(0, 0, 0) or palette.Accent
    local old = {}
    for key, value in pairs(C) do old[key] = value end
    -- Recolour already-created interface objects by matching their palette role.
    for _, object in ipairs(SG:GetDescendants()) do
        if object ~= ThemeEffectFrame then
            if object:IsA("GuiObject") then
                for key, oldColor in pairs(old) do
                    if palette[key] and object.BackgroundColor3 == oldColor then object.BackgroundColor3 = palette[key] end
                    if palette[key] and (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox"))
                        and object.TextColor3 == oldColor then object.TextColor3 = palette[key] end
                end
            elseif object:IsA("UIStroke") then
                for key, oldColor in pairs(old) do
                    if palette[key] and object.Color == oldColor then object.Color = palette[key] end
                end
            end
        end
    end
    for key, value in pairs(palette) do C[key] = value end
    -- Background effects remain visible in the sidebar and underneath its tabs.
    if theme == "Rain" then
        -- Header and sidebar merge into the same background as the feature area.
        Sidebar.BackgroundColor3 = palette.BG
        Sidebar.BackgroundTransparency = 1
        Hdr.BackgroundColor3 = palette.BG
        Hdr.BackgroundTransparency = 1
    elseif theme == "Cosmic" then
        Sidebar.BackgroundColor3 = palette.Sidebar
        Sidebar.BackgroundTransparency = 0.18
        Hdr.BackgroundColor3 = palette.Sidebar
        Hdr.BackgroundTransparency = 0
    elseif theme == "Sakura" then
        Sidebar.BackgroundColor3 = palette.Sidebar
        -- Petals remain visible behind the complete sidebar and its tabs.
        Sidebar.BackgroundTransparency = 0.55
        -- Let petals remain visible behind the logo, title and INS badge.
        Hdr.BackgroundColor3 = palette.Sidebar
        Hdr.BackgroundTransparency = 0.55
    else
        Sidebar.BackgroundColor3 = palette.Sidebar
        Sidebar.BackgroundTransparency = 0
        Hdr.BackgroundColor3 = palette.Sidebar
        Hdr.BackgroundTransparency = 0
    end
    for _, tabName in ipairs(TabN) do
        local tab = TabB[tabName]
        if tab then
            tab.TextColor3 = tabName == CurTab and palette.TOn or palette.TDim
            tab.BackgroundTransparency = theme == "Rain" and 0.25
                or (theme == "Sakura" and 0.18)
                or (theme == "Cosmic" and 0.12)
                or 0
        end
    end
    -- Force both the switch track and knob to use the selected theme palette.
    -- Use palette values directly so no old gray colour can survive recolouring.
    for _, object in ipairs(SG:GetDescendants()) do
        if object:GetAttribute("ThemeSwitch") then
            local knob = object:FindFirstChildOfClass("Frame")
            local enabled = knob and knob.Position.X.Scale > 0.5
            object.BackgroundColor3 = enabled and palette.Accent or palette.SwOff
            if knob then
                knob.BackgroundColor3 = enabled and palette.TMain or palette.KnOff
            end
        elseif object:GetAttribute("ThemeSliderFill") then
            object.BackgroundColor3 = palette.Accent
        elseif object:GetAttribute("ThemeSliderKnob") then
            object.BackgroundColor3 = palette.TMain
        elseif object:GetAttribute("ThemeToggleCard") then
            local enabled = false
            for _, child in ipairs(object:GetChildren()) do
                if child:GetAttribute("ThemeSwitch") then
                    local knob = child:FindFirstChildOfClass("Frame")
                    enabled = knob and knob.Position.X.Scale > 0.5 or false
                    break
                end
            end
            object.BackgroundColor3 = enabled and palette.CardOn or palette.Card
            for _, child in ipairs(object:GetChildren()) do
                if child:IsA("TextLabel") then
                    child.TextColor3 = child.TextSize >= 13
                        and (enabled and palette.TOn or palette.TMain)
                        or palette.TDim
                end
            end
        end
    end
    Config.Theme = theme
    StartThemeEffect(theme)
    if RefreshThemesUI then RefreshThemesUI() end
end
-- Keep switch colours forced every frame. Some feature Refresh tweens can otherwise
-- restore the old gray switch colours after a theme has already been applied.
themeSwitchRefreshElapsed = 0
table.insert(Connections, RunService.RenderStepped:Connect(function(dt)
    if not ScriptAlive then return end
    themeSwitchRefreshElapsed = themeSwitchRefreshElapsed + dt
    if themeSwitchRefreshElapsed < 0.1 then return end
    themeSwitchRefreshElapsed = 0
    local palette = ThemePalettes[Config.Theme or "Cosmic"] or ThemePalettes.Cosmic
    for _, object in ipairs(SG:GetDescendants()) do
        if object:GetAttribute("ThemeSwitch") then
            local knob = object:FindFirstChildOfClass("Frame")
            local enabled = knob and knob.Position.X.Scale > 0.5
            object.BackgroundColor3 = enabled and palette.Accent or palette.SwOff
            if knob then
                knob.BackgroundColor3 = enabled and palette.TMain or palette.KnOff
            end
        elseif object:GetAttribute("ThemeSliderFill") then
            object.BackgroundColor3 = palette.Accent
        elseif object:GetAttribute("ThemeSliderKnob") then
            object.BackgroundColor3 = palette.TMain
        elseif object:GetAttribute("ThemeToggleCard") then
            local enabled = false
            for _, child in ipairs(object:GetChildren()) do
                if child:GetAttribute("ThemeSwitch") then
                    local knob = child:FindFirstChildOfClass("Frame")
                    enabled = knob and knob.Position.X.Scale > 0.5 or false
                    break
                end
            end
            object.BackgroundColor3 = enabled and palette.CardOn or palette.Card
            for _, child in ipairs(object:GetChildren()) do
                if child:IsA("TextLabel") then
                    child.TextColor3 = child.TextSize >= 13
                        and (enabled and palette.TOn or palette.TMain)
                        or palette.TDim
                end
            end
        end
    end
end))
-- Drag
local Dragging, DragStart, StartPos
Hdr.InputBegan:Connect(function(Inp)
    if Inp.UserInputType == Enum.UserInputType.MouseButton1 then
        Dragging = true
        DragStart = Inp.Position
        StartPos = MF.Position
        Inp.Changed:Connect(function()
            if Inp.UserInputState == Enum.UserInputState.End then Dragging = false end
        end)
    end
end)
table.insert(Connections, UIS.InputChanged:Connect(function(Inp)
    if Dragging and Inp.UserInputType == Enum.UserInputType.MouseMovement then
        local D = Inp.Position - DragStart
        MF.Position = UDim2.new(StartPos.X.Scale, StartPos.X.Offset + D.X, StartPos.Y.Scale, StartPos.Y.Offset + D.Y)
    end
end))
-- ═══════ SLIDER ═══════
local function CreateSlider(Name, Min, Max, Default, Parent, YPos, Color, Callback, LinkedToggle)
    local Con = Instance.new("Frame")
    Con.Size = UDim2.new(1, 0, 0, 45)
    Con.Position = UDim2.new(0, 0, 0, YPos)
    Con.BackgroundTransparency = 1
    Con.Parent = Parent
    RegisterSearchEntry(Name, Parent, YPos, Con)
    local Lbl = Instance.new("TextLabel")
    Lbl.Size = UDim2.new(1, 0, 0, 14)
    Lbl.BackgroundTransparency = 1
    Lbl.TextColor3 = C.TDim
    Lbl.TextXAlignment = Enum.TextXAlignment.Left
    Lbl.Font = Enum.Font.Gotham
    Lbl.TextSize = 12
    Lbl.Text = Name
    Lbl.TextStrokeTransparency = 1
    Lbl.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    Lbl.Parent = Con
    local ValLbl = Instance.new("TextBox")
    ValLbl.Size = UDim2.new(0, 50, 0, 18)
    ValLbl.Position = UDim2.new(1, -50, 0, -2)
    ValLbl.BackgroundColor3 = C.Track
    ValLbl.BackgroundTransparency = 0
    ValLbl.BorderSizePixel = 0
    ValLbl.TextColor3 = C.TMain
    ValLbl.TextXAlignment = Enum.TextXAlignment.Center
    ValLbl.Font = Enum.Font.GothamBold
    ValLbl.TextSize = 12
    ValLbl.Text = tostring(Default)
    ValLbl.ClearTextOnFocus = false
    ValLbl.TextStrokeTransparency = 1
    ValLbl.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    ValLbl.ZIndex = 3
    ValLbl.Parent = Con
    Instance.new("UICorner", ValLbl).CornerRadius = UDim.new(0, 5)
    MakeStroke(ValLbl, C.Border, 1)
    local Trk = Instance.new("Frame")
    Trk.Size = UDim2.new(1, 0, 0, 8)
    Trk.Position = UDim2.new(0, 0, 0, 22)
    Trk.BackgroundColor3 = C.Track
    Trk.BorderSizePixel = 0
    Trk.Parent = Con
    Instance.new("UICorner", Trk).CornerRadius = UDim.new(1, 0)
    local Pct = (Default - Min) / math.max(Max - Min, 1e-9)
    local Fill = Instance.new("Frame")
    Fill.Size = UDim2.new(Pct, 0, 1, 0)
    Fill.BackgroundColor3 = Color
    Fill.BorderSizePixel = 0
    Fill:SetAttribute("ThemeSliderFill", true)
    Fill.Parent = Trk
    Instance.new("UICorner", Fill).CornerRadius = UDim.new(1, 0)
    local Knb = Instance.new("Frame")
    Knb.Size = UDim2.new(0, 18, 0, 18)
    Knb.Position = UDim2.new(Pct, -9, 0.5, -9)
    Knb.BackgroundColor3 = Color3.fromRGB(255,255,255)
    Knb.BorderSizePixel = 0
    Knb:SetAttribute("ThemeSliderKnob", true)
    Knb.Parent = Con
    Instance.new("UICorner", Knb).CornerRadius = UDim.new(1, 0)
    local Clk = Instance.new("TextButton")
    Clk.Size = UDim2.new(1, 0, 1, 0)
    Clk.BackgroundTransparency = 1
    Clk.Text = ""
    Clk.AutoButtonColor = false
    Clk.BorderSizePixel = 0
    Clk.TextStrokeTransparency = 1
    Clk.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    Clk.Parent = Con
    -- Linked sliders use the editable value box in their toggle card;
    -- hide the duplicate value box on the slider row.
    if LinkedToggle then ValLbl.Visible = false end
    local isDecimal = Min % 1 ~= 0 or Max % 1 ~= 0 or Default % 1 ~= 0 or Name == "Interaction Delay"
    local SD = {Trk=Trk, Fill=Fill, Knb=Knb, Lbl=Lbl, ValLbl=ValLbl, Min=Min, Max=Max, Name=Name, Callback=Callback, LinkedToggle=LinkedToggle, Dragging=false, Decimal=isDecimal}
    function SD:Normalize(v)
        return self.Decimal and (math.floor(v * 100 + 0.5) / 100) or math.floor(v)
    end
    function SD:Format(v)
        return self.Decimal and string.format("%.2f", v) or tostring(v)
    end
    function SD:SetValue(v, silent)
        v = math.clamp(self:Normalize(v), self.Min, self.Max)
        local p = (v - self.Min) / math.max(self.Max - self.Min, 1e-9)
        self.Fill.Size = UDim2.new(p, 0, 1, 0)
        self.Knb.Position = UDim2.new(p, -9, 0.5, -9)
        self.ValLbl.Text = self:Format(v)
        if self.LinkedToggle and ToggleValueLabels[self.LinkedToggle] then
            ToggleValueLabels[self.LinkedToggle].Text = self:Format(v)
        end
        if not silent then self.Callback(v) end
    end
    function SD:SetCustomValue(v, silent)
        v = self:Normalize(v)
        if self.Decimal then v = math.clamp(v, self.Min, self.Max) end
        local visual = math.clamp(v, self.Min, self.Max)
        local p = (visual - self.Min) / math.max(self.Max - self.Min, 1e-9)
        self.Fill.Size = UDim2.new(p, 0, 1, 0)
        self.Knb.Position = UDim2.new(p, -9, 0.5, -9)
        self.ValLbl.Text = self:Format(v)
        if self.LinkedToggle and ToggleValueLabels[self.LinkedToggle] then
            ToggleValueLabels[self.LinkedToggle].Text = self:Format(v)
        end
        if not silent then self.Callback(v) end
    end
    ValLbl.Focused:Connect(function()
        SD.Dragging = false
        ValLbl.TextColor3 = Color
    end)
    ValLbl.FocusLost:Connect(function()
        ValLbl.TextColor3 = C.TMain
        local value = tonumber(ValLbl.Text:gsub("%s", ""))
        if not value then
            ValLbl.Text = tostring(Default)
            return
        end
        SD:SetCustomValue(value, false)
    end)
    Clk.ZIndex = 1
    Clk.MouseButton1Down:Connect(function() SD.Dragging = true end)
    table.insert(AllSliders, SD)
    -- Initialize linked toggle label with default value
    if LinkedToggle and ToggleValueLabels[LinkedToggle] then
        local toggleValueBox = ToggleValueLabels[LinkedToggle]
        toggleValueBox.Visible = true
        toggleValueBox.Text = SD:Format(Default)
        -- Linked toggles need room for the editable value field. Toggles without
        -- a linked slider keep their bind and switch aligned at the far right.
        if LinkedToggle ~= "Aim Assistant" then
            local linkedBind = BindButtons[LinkedToggle]
            if linkedBind then linkedBind.Position = UDim2.new(1, -136, 0.5, -10) end
            local linkedCard = toggleValueBox.Parent
            if linkedCard then
                for _, child in ipairs(linkedCard:GetChildren()) do
                    if child:IsA("TextButton") and child.Text == "" and child.Size.X.Offset == 46 then
                        child.Position = UDim2.new(1, -95, 0.5, -13)
                        break
                    end
                end
            end
        end
        if toggleValueBox:IsA("TextBox") then
            toggleValueBox.BackgroundColor3 = C.Track
            toggleValueBox.BackgroundTransparency = 0
            toggleValueBox.BorderSizePixel = 0
            if not toggleValueBox:FindFirstChildOfClass("UICorner") then
                Instance.new("UICorner", toggleValueBox).CornerRadius = UDim.new(0, 5)
                MakeStroke(toggleValueBox, C.Border, 1)
            end
            toggleValueBox.Focused:Connect(function()
                SD.Dragging = false
                toggleValueBox.TextColor3 = Color
            end)
            toggleValueBox.FocusLost:Connect(function()
                toggleValueBox.TextColor3 = C.TDim
                local value = tonumber(toggleValueBox.Text:gsub("%s", ""))
                if not value then
                    toggleValueBox.Text = SD.ValLbl.Text
                    return
                end
                SD:SetCustomValue(value, false)
            end)
        end
    end
    return Con
end
table.insert(Connections, RunService.RenderStepped:Connect(function()
    if not ScriptAlive then return end
    for _, S in ipairs(AllSliders) do
        if S.Dragging then
            local MX = UIS:GetMouseLocation().X
            local TX = S.Trk.AbsolutePosition.X
            local TW = S.Trk.AbsoluteSize.X
            if TW > 0 then
                local P = math.clamp((MX - TX) / TW, 0, 1)
                local rawValue = S.Min + P * (S.Max - S.Min)
                local V = math.clamp(S:Normalize(rawValue), S.Min, S.Max)
                P = (V - S.Min) / math.max(S.Max - S.Min, 1e-9)
                S.Fill.Size = UDim2.new(P, 0, 1, 0)
                S.Knb.Position = UDim2.new(P, -9, 0.5, -9)
                S.ValLbl.Text = S:Format(V)
                if S.LinkedToggle and ToggleValueLabels[S.LinkedToggle] then
                    ToggleValueLabels[S.LinkedToggle].Text = S:Format(V)
                end
                S.Callback(V)
            end
        end
    end
end))
table.insert(Connections, UIS.InputEnded:Connect(function(Inp)
    if Inp.UserInputType == Enum.UserInputType.MouseButton1 then
        for _, S in ipairs(AllSliders) do S.Dragging = false end
    end
end))
