    local Sw = Instance.new("TextButton")
    Sw.Size = UDim2.new(0, 46, 0, 26)
    Sw.Position = UDim2.new(1, -68, 0.5, -13)
    Sw.BackgroundColor3 = C.SwOff
    Sw.BorderSizePixel = 0
    Sw.Text = ""
    Sw.TextStrokeTransparency = 1
    Sw.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    Sw.Parent = Card
    Sw:SetAttribute("ThemeSwitch", true)
    Instance.new("UICorner", Sw).CornerRadius = UDim.new(1, 0)
    local ValLbl = Instance.new("TextBox")
    ValLbl.Size = UDim2.new(0, 40, 0, 22)
    ValLbl.Position = UDim2.new(1, -44, 0.5, -11)
    ValLbl.BackgroundTransparency = 1
    ValLbl.TextColor3 = C.TDim
    ValLbl.TextXAlignment = Enum.TextXAlignment.Center
    ValLbl.Font = Enum.Font.GothamBold
    ValLbl.TextSize = 12
    ValLbl.Text = ""
    ValLbl.ClearTextOnFocus = false
    ValLbl.TextEditable = true
    -- Hidden by default; CreateSlider reveals it only for linked numeric toggles.
    ValLbl.Visible = false
    ValLbl.TextStrokeTransparency = 1
    ValLbl.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    ValLbl.Parent = Card
    ToggleValueLabels[Name] = ValLbl
    local Kn = Instance.new("Frame")
    Kn.Size = UDim2.new(0, 20, 0, 20)
    Kn.Position = UDim2.new(0, 3, 0.5, -10)
    Kn.BackgroundColor3 = C.KnOff
    Kn.BorderSizePixel = 0
    Kn.Parent = Sw
    Instance.new("UICorner", Kn).CornerRadius = UDim.new(1, 0)
    local IsOn = false
    local Fast = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local function Refresh()
        if IsOn then
            TweenService:Create(Kn, Fast, {Position = UDim2.new(1, -23, 0.5, -10), BackgroundColor3 = Color3.fromRGB(255,255,255)}):Play()
            TweenService:Create(Sw, Fast, {BackgroundColor3 = C.Accent}):Play()
            TweenService:Create(CS, Fast, {Color = Color}):Play()
            TweenService:Create(Card, Fast, {BackgroundColor3 = C.CardOn}):Play()
            NL.TextColor3 = C.TOn
        else
            TweenService:Create(Kn, Fast, {Position = UDim2.new(0, 3, 0.5, -10), BackgroundColor3 = C.KnOff}):Play()
            TweenService:Create(Sw, Fast, {BackgroundColor3 = C.SwOff}):Play()
            TweenService:Create(CS, Fast, {Color = C.Border}):Play()
            TweenService:Create(Card, Fast, {BackgroundColor3 = C.Card}):Play()
            NL.TextColor3 = C.TMain
        end
    end
    local function Toggle() IsOn = not IsOn; Refresh(); Callback(IsOn) end
    ToggleFuncs[Name] = Toggle
    ToggleSetters[Name] = function(v, silent)
        IsOn = v
        Refresh()
        if not silent then Callback(IsOn) end
    end
    Sw.MouseButton1Click:Connect(Toggle)
    BindBtn.MouseButton1Click:Connect(function()
        ListeningBind = Name
        BindBtn.Text = "..."
        BindBtn.TextColor3 = C.Accent
    end)
    Refresh()
    return Card
end
