    Btn.TextStrokeTransparency = 1
    Btn.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    Btn.Parent = Card
    local Fast = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    Btn.MouseEnter:Connect(function()
        TweenService:Create(Card, Fast, {BackgroundColor3 = C.CardHover}):Play()
        TweenService:Create(CS, Fast, {Color = Color}):Play()
        NL.TextColor3 = C.TOn
    end)
    Btn.MouseLeave:Connect(function()
        TweenService:Create(Card, Fast, {BackgroundColor3 = C.Card}):Play()
        TweenService:Create(CS, Fast, {Color = C.Border}):Play()
        NL.TextColor3 = C.TMain
    end)
    Btn.MouseButton1Click:Connect(function()
        Card.BackgroundColor3 = Color
        NL.TextColor3 = Color3.fromRGB(255,255,255)
        task.wait(0.1)
        TweenService:Create(Card, Fast, {BackgroundColor3 = C.Card}):Play()
        NL.TextColor3 = C.TMain
        Callback()
    end)
    return Card
