    Instance.new("UICorner", menu).CornerRadius = UDim.new(0, 8)
    local menuStroke = MakeStroke(menu, C.Border, 1)
    menuStroke.Transparency = 1
    local options = {"Full", "Corner"}
    local buttons = {}
    local opened = false
    local function RefreshType()
        selectedLabel.Text = (ESPConfig.BoxType or "Full") .. (opened and " ▲" or " ▼")
        for i, button in ipairs(buttons) do
            local selected = options[i] == ESPConfig.BoxType
            button.BackgroundColor3 = selected and C.CardOn or C.Card
            button.TextColor3 = selected and C.TOn or C.TMain
        end
    end
    for i, option in ipairs(options) do
        local button = Instance.new("TextButton")
        button.Size = UDim2.new(1, -8, 0, 28)
        button.Position = UDim2.new(0, 4, 0, 4 + (i-1)*30)
        button.BackgroundColor3 = C.Card
        button.BackgroundTransparency = 1
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = option
        button.TextColor3 = C.TMain
        button.TextTransparency = 1
        button.Font = Enum.Font.GothamBold
        button.TextSize = 11
        button.TextStrokeTransparency = 1
        button.ZIndex = 51
        button.Parent = menu
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 6)
        buttons[i] = button
        button.MouseButton1Click:Connect(function()
            ESPConfig.BoxType = option
            RefreshType()
            UpdateESP()
        end)
    end
    RefreshBoxTypeUI = RefreshType
    RefreshType()
    local anim = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    arrow.MouseButton1Click:Connect(function()
        opened = not opened
        selectedLabel.Text = (ESPConfig.BoxType or "Full") .. (opened and " ▲" or " ▼")
        arrow.TextColor3 = opened and C.TOn or C.TDim
        if opened then
            BoxESPCard.ZIndex = 40
            arrow.ZIndex = 52
            menu.Visible = true
            TweenService:Create(menu, anim, {Size=UDim2.new(0,126,0,66), BackgroundTransparency=0}):Play()
            TweenService:Create(menuStroke, anim, {Transparency=0}):Play()
            for _, button in ipairs(buttons) do
                TweenService:Create(button, anim, {BackgroundTransparency=0, TextTransparency=0}):Play()
            end
        else
            TweenService:Create(menu, anim, {Size=UDim2.new(0,126,0,0), BackgroundTransparency=1}):Play()
            TweenService:Create(menuStroke, anim, {Transparency=1}):Play()
            for _, button in ipairs(buttons) do
                TweenService:Create(button, anim, {BackgroundTransparency=1, TextTransparency=1}):Play()
            end
            task.delay(0.2, function()
                if not opened then menu.Visible=false; BoxESPCard.ZIndex=1; arrow.ZIndex=8 end
            end)
        end
    end)
end
