-- FRIENDS
-- Selected users are ignored by combat features; their ESP boxes use RGB.
do
    local function BuildFriendsList()
        for _, child in ipairs(Pages.FRIENDS:GetChildren()) do
            if child.Name == "FriendPlayerRow" then child:Destroy() end
        end
        local players = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then table.insert(players, player) end
        end
        table.sort(players, function(a, b) return a.Name:lower() < b.Name:lower() end)
        if #players == 0 then
            local empty = Instance.new("TextLabel")
            empty.Name = "FriendPlayerRow"
            empty.Size = UDim2.new(1, 0, 0, 42)
            empty.Position = UDim2.new(0, 0, 0, 0)
            empty.BackgroundColor3 = C.Card
            empty.BorderSizePixel = 0
            empty.Text = "No other players on this server"
            empty.TextColor3 = C.TDim
            empty.Font = Enum.Font.Gotham
            empty.TextSize = 11
            empty.TextStrokeTransparency = 1
            empty.Parent = Pages.FRIENDS
            Instance.new("UICorner", empty).CornerRadius = UDim.new(0, 8)
            MakeStroke(empty, C.Border, 1)
            return
        end
        for index, player in ipairs(players) do
            local selected = IsCheatFriend(player)
            local row = Instance.new("TextButton")
            row.Name = "FriendPlayerRow"
            row.Size = UDim2.new(1, 0, 0, 46)
            row.Position = UDim2.new(0, 0, 0, (index - 1) * 52)
            row.BackgroundColor3 = selected and C.CardOn or C.Card
            row.BorderSizePixel = 0
            row.AutoButtonColor = false
            row.Text = ""
            row.Parent = Pages.FRIENDS
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 8)
            local stroke = MakeStroke(row, selected and C.Accent or C.Border, 1)
            -- Avatar bust on the left side of the row.
            local avatar = Instance.new("ImageLabel")
            avatar.Size = UDim2.new(0, 36, 0, 36)
            avatar.Position = UDim2.new(0, 7, 0.5, -18)
            avatar.BackgroundColor3 = C.Track
            avatar.BorderSizePixel = 0
            avatar.Image = ""
            avatar.ScaleType = Enum.ScaleType.Crop
            avatar.Parent = row
            Instance.new("UICorner", avatar).CornerRadius = UDim.new(0, 7)
            MakeStroke(avatar, selected and C.Accent or C.Border, 1)
            task.spawn(function()
                local ok, image = pcall(function()
                    return Players:GetUserThumbnailAsync(
                        player.UserId,
                        Enum.ThumbnailType.AvatarBust,
                        Enum.ThumbnailSize.Size100x100
                    )
                end)
                if ok and avatar and avatar.Parent then avatar.Image = image end
            end)
            -- Player text is centred in the space between avatar and action button.
            local nameLabel = Instance.new("TextLabel")
            nameLabel.Size = UDim2.new(1, -116, 0, 16)
            nameLabel.Position = UDim2.new(0, 48, 0, 7)
            nameLabel.BackgroundTransparency = 1
            nameLabel.Text = player.DisplayName
            nameLabel.TextColor3 = selected and C.TOn or C.TMain
            nameLabel.TextXAlignment = Enum.TextXAlignment.Center
            nameLabel.Font = Enum.Font.GothamBold
            nameLabel.TextSize = 12
            nameLabel.TextStrokeTransparency = 1
            nameLabel.Parent = row
            local userLabel = Instance.new("TextLabel")
            userLabel.Size = UDim2.new(1, -116, 0, 13)
            userLabel.Position = UDim2.new(0, 48, 0, 25)
            userLabel.BackgroundTransparency = 1
            userLabel.Text = "@" .. player.Name
            userLabel.TextColor3 = C.TDim
            userLabel.TextXAlignment = Enum.TextXAlignment.Center
            userLabel.Font = Enum.Font.Gotham
            userLabel.TextSize = 10
            userLabel.TextStrokeTransparency = 1
            userLabel.Parent = row
            local state = Instance.new("TextLabel")
            state.Size = UDim2.new(0, 50, 0, 24)
            state.Position = UDim2.new(1, -60, 0.5, -12)
            state.BackgroundColor3 = selected and C.Accent or C.Track
            state.BorderSizePixel = 0
            state.Text = selected and "FRIEND" or "ADD"
            state.TextColor3 = selected and C.BG or C.TDim
            state.Font = Enum.Font.GothamBold
            state.TextSize = 9
            state.TextStrokeTransparency = 1
            state.Parent = row
            Instance.new("UICorner", state).CornerRadius = UDim.new(0, 6)
            row.MouseButton1Click:Connect(function()
                Config.Friends = Config.Friends or {}
                local key = tostring(player.UserId)
                Config.Friends[key] = not IsCheatFriend(player) or nil
                BuildFriendsList()
            end)
            row.MouseEnter:Connect(function() row.BackgroundColor3 = C.CardHover end)
            row.MouseLeave:Connect(function()
                row.BackgroundColor3 = IsCheatFriend(player) and C.CardOn or C.Card
                stroke.Color = IsCheatFriend(player) and C.Accent or C.Border
            end)
        end
    end
    RefreshFriendsUI = BuildFriendsList
    BuildFriendsList()
    table.insert(Connections, Players.PlayerAdded:Connect(function() task.defer(BuildFriendsList) end))
    table.insert(Connections, Players.PlayerRemoving:Connect(function() task.defer(BuildFriendsList) end))
end
-- TELEPORT
local ActiveLocationMenu = nil
local function OpenLocationMenu(mode)
    if ActiveLocationMenu then ActiveLocationMenu:Destroy(); ActiveLocationMenu = nil end
    Config.SavedLocations = Config.SavedLocations or {false, false, false}
    local root = Instance.new("Frame")
    root.Name = "LocationSlotMenu"
    root.Size = UDim2.new(1, 0, 1, 0)
    root.BackgroundTransparency = 1
    root.ZIndex = 100
    root.Parent = SG
    ActiveLocationMenu = root
    local backdrop = Instance.new("TextButton")
    backdrop.Size = UDim2.new(1, 0, 1, 0)
    backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    backdrop.BackgroundTransparency = 0.5
    backdrop.BorderSizePixel = 0
    backdrop.Text = ""
    backdrop.AutoButtonColor = false
    backdrop.ZIndex = 100
    backdrop.Parent = root
    local pop = Instance.new("Frame")
    pop.Size = UDim2.new(0, 280, 0, 202)
    pop.Position = UDim2.new(0.5, -140, 0.5, -101)
    pop.BackgroundColor3 = C.BG
    pop.BorderSizePixel = 0
    pop.ZIndex = 101
    pop.Parent = root
    Instance.new("UICorner", pop).CornerRadius = UDim.new(0, 12)
    MakeStroke(pop, C.Accent, 1)
    local title = Instance.new("TextLabel")
    title.Size = UDim2.new(1, -50, 0, 24)
    title.Position = UDim2.new(0, 12, 0, 9)
    title.BackgroundTransparency = 1
    title.Text = mode == "save" and "Save Location" or "Teleport Location"
    title.TextColor3 = C.TMain
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Font = Enum.Font.GothamBold
    title.TextSize = 14
    title.TextStrokeTransparency = 1
    title.ZIndex = 102
    title.Parent = pop
    local close = Instance.new("TextButton")
    close.Size = UDim2.new(0, 26, 0, 24)
    close.Position = UDim2.new(1, -34, 0, 8)
    close.BackgroundColor3 = C.Card
    close.BorderSizePixel = 0
    close.Text = "X"
    close.TextColor3 = C.TDim
    close.Font = Enum.Font.GothamBold
    close.TextSize = 11
    close.TextStrokeTransparency = 1
    close.ZIndex = 102
    close.Parent = pop
    Instance.new("UICorner", close).CornerRadius = UDim.new(0, 6)
    local function CloseMenu()
        if root and root.Parent then root:Destroy() end
        if ActiveLocationMenu == root then ActiveLocationMenu = nil end
    end
    close.MouseButton1Click:Connect(CloseMenu)
    backdrop.MouseButton1Click:Connect(CloseMenu)
    for i = 1, 3 do
        local saved = Config.SavedLocations[i]
        local slot = Instance.new("TextButton")
        slot.Size = UDim2.new(1, -20, 0, 44)
        slot.Position = UDim2.new(0, 10, 0, 40 + (i - 1) * 50)
        slot.BackgroundColor3 = saved and C.CardOn or C.Card
        slot.BorderSizePixel = 0
        slot.AutoButtonColor = false
        slot.TextColor3 = saved and C.TOn or C.TMain
        slot.TextXAlignment = Enum.TextXAlignment.Left
        slot.Font = Enum.Font.GothamBold
        slot.TextSize = 12
        slot.TextStrokeTransparency = 1
        slot.ZIndex = 102
        slot.Parent = pop
        Instance.new("UICorner", slot).CornerRadius = UDim.new(0, 8)
        MakeStroke(slot, saved and C.Accent or C.Border, 1)
        if saved and type(saved) == "table" then
            slot.Text = string.format("   Slot %d     %.1f, %.1f, %.1f", i, saved.X or 0, saved.Y or 0, saved.Z or 0)
        else
            slot.Text = "   Slot " .. i .. "     Empty"
        end
        slot.MouseEnter:Connect(function() slot.BackgroundColor3 = C.CardHover end)
        slot.MouseLeave:Connect(function()
            local current = Config.SavedLocations[i]
            slot.BackgroundColor3 = current and C.CardOn or C.Card
        end)
        slot.MouseButton1Click:Connect(function()
            if mode == "save" then
                local character = LocalPlayer.Character
                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local pos = hrp.Position
                Config.SavedLocations[i] = {X = pos.X, Y = pos.Y, Z = pos.Z}
                pcall(function()
                    StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text="Location saved to Slot "..i, Duration=3})
                end)
                CloseMenu()
            else
                local point = Config.SavedLocations[i]
                if not point or type(point) ~= "table" then
                    pcall(function()
                        StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text="Slot "..i.." is empty", Duration=3})
                    end)
                    return
                end
                local character = LocalPlayer.Character
                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hrp.CFrame = CFrame.new(point.X or 0, point.Y or 0, point.Z or 0)
                    CloseMenu()
                end
            end
        end)
    end
end
local SaveLocationCard = CreateAction("Save Location", Pages.MISC, 478, C.Green, function()
    OpenLocationMenu("save")
end)
local TeleportLocationCard = CreateAction("Teleport Location", Pages.MISC, 532, C.Blue, function()
