    for _, child in ipairs(actionCard:GetChildren()) do
        if child:IsA("Frame") and child.Size.X.Offset == 32 and child.Size.Y.Offset == 32 then
            child:Destroy()
        elseif child:IsA("TextLabel") and child.Position.X.Offset == 48 then
            child.Position = UDim2.new(0, 14, child.Position.Y.Scale, child.Position.Y.Offset)
            child.Size = UDim2.new(1, -28, child.Size.Y.Scale, child.Size.Y.Offset)
        end
    end
end
