        CNL.TextColor3 = C.TMain
    end)
    ToggleFuncs["TpToCoord"] = function()
        local char = LocalPlayer.Character
        local Root = char and char:FindFirstChild("HumanoidRootPart")
        if not Root then return end
        local lookFlat  = Vector3.new(Root.CFrame.LookVector.X,  0, Root.CFrame.LookVector.Z).Unit
        local rightFlat = Vector3.new(Root.CFrame.RightVector.X, 0, Root.CFrame.RightVector.Z).Unit
        local offset = rightFlat            * Config.CoordX
                     + Vector3.new(0, 1, 0) * Config.CoordY
                     + lookFlat             * Config.CoordZ
        local newPos = Root.Position + offset
        local rx, ry, rz = Root.CFrame:ToOrientation()
        Root.CFrame = CFrame.new(newPos) * CFrame.fromOrientation(rx, ry, rz)
        CSub.Text = "X:"..Config.CoordX.."  Y:"..Config.CoordY.."  Z:"..Config.CoordZ
        CoordCard.BackgroundColor3 = coordColor
