        task.wait(0.1)
        TweenService:Create(CoordCard, CFast, {BackgroundColor3 = C.Card}):Play()
        CNL.TextColor3 = C.TMain
    end
    CBtn.MouseButton1Click:Connect(function()
        ToggleFuncs["TpToCoord"]()
