-- ── AIM ASSISTANT ────────────────────────────────────────────
local AimConn = nil
CurrentAimHumanoid = nil
local function StopAim()
    if AimConn then AimConn:Disconnect(); AimConn = nil end
    CurrentAimHumanoid = nil
end
local function StartAim()
    StopAim()
    AimConn = RunService.RenderStepped:Connect(function()
        CurrentAimHumanoid = nil
        if not ScriptAlive or not Config.AimEnabled or Config.AimFOV == 0 then return end
        if Config.FreeCamEnabled then return end
        local cam    = workspace.CurrentCamera
        local lChar  = LocalPlayer.Character
        if not lChar then return end
        local halfFov = math.rad(Config.AimFOV / 2)
        local bestDist, bestHead, bestHumanoid = math.huge, nil, nil
        for _, p in ipairs(Players:GetPlayers()) do
            if p == LocalPlayer or IsCheatFriend(p) then continue end
            local char = p.Character
            if not char then continue end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum or hum.Health <= 0 then continue end
            local selected = Config.AimHitboxes or {Head=true}
            local candidates = {}
            local function AddPart(name)
                local part = char:FindFirstChild(name)
                if part and part:IsA("BasePart") then table.insert(candidates, part) end
            end
            if selected.Head then AddPart("Head") end
            if selected.Torso then
                AddPart("UpperTorso"); AddPart("LowerTorso"); AddPart("Torso")
            end
            if selected.Arms then
                for _, name in ipairs({"Left Arm", "Right Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand"}) do AddPart(name) end
            end
            if selected.Legs then
                for _, name in ipairs({"Left Leg", "Right Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot"}) do AddPart(name) end
            end
            -- Neck is a joint, not a BasePart. Use the midpoint between Head and upper torso.
            if selected.Neck then
                local h = char:FindFirstChild("Head")
                local t = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
                if h and t and h:IsA("BasePart") and t:IsA("BasePart") then
                    table.insert(candidates, {Position = (h.Position + t.Position) * 0.5})
                end
            end
            for _, target in ipairs(candidates) do
                local targetDirection = target.Position - cam.CFrame.Position
                -- Auto Wall ON allows targets through geometry. When it is OFF,
                -- the first ray hit must belong to the target character.
                if not Config.AutoWallEnabled then
                    local visibilityParams = RaycastParams.new()
                    visibilityParams.FilterType = Enum.RaycastFilterType.Exclude
                    visibilityParams.FilterDescendantsInstances = {lChar}
                    visibilityParams.IgnoreWater = true
                    local wallHit = workspace:Raycast(cam.CFrame.Position, targetDirection, visibilityParams)
                    if wallHit and not wallHit.Instance:IsDescendantOf(char) then
                        continue
                    end
                end
                local toTarget = targetDirection.Unit
                local angle = math.acos(math.clamp(cam.CFrame.LookVector:Dot(toTarget), -1, 1))
                if angle <= halfFov then
                    local sp, onScreen = cam:WorldToViewportPoint(target.Position)
                    if onScreen then
                        local vp = cam.ViewportSize
                        local dx, dy = sp.X - vp.X / 2, sp.Y - vp.Y / 2
                        local cursorDist = math.sqrt(dx*dx + dy*dy)
                        local priority = Config.AimPriority or "cursor"
                        local score
                        if priority == "distant" then
                            -- Prioritize the physically nearest valid target.
                            score = (target.Position - cam.CFrame.Position).Magnitude * 1000 + cursorDist
                        elseif priority == "heal" then
                            -- Prioritize the enemy with the lowest current health.
                            score = hum.Health * 100000 + cursorDist
                        else
                            -- Prioritize the hitbox nearest to the mouse/screen centre.
                            score = cursorDist
                        end
                        if score < bestDist then bestDist = score; bestHead = target; bestHumanoid = hum end
                    end
                end
            end
        end
        if not bestHead then return end
        CurrentAimHumanoid = bestHumanoid
        local alpha    = 1 - (Config.AimSmooth / 10) * 0.95
        local targetCF = CFrame.new(cam.CFrame.Position, bestHead.Position)
        cam.CFrame     = cam.CFrame:Lerp(targetCF, alpha)
    end)
end
-- ══════════════════════════════════════════════
--   HIT SOUND — monitors health of the current Aim Assistant target.
-- ══════════════════════════════════════════════
HitSoundWatchConn = nil
HitSoundInputConn = nil
HitSoundLocalAttackUntil = 0
HitSoundAttackSoundPlayed = false
HitSoundNextHeldArm = 0
HitSoundAbilityUntil = 0
HitSoundLastPlayback = -math.huge
HitSoundHealthConns = setmetatable({}, {__mode="k"})
HitSoundLastHealth = setmetatable({}, {__mode="k"})
HitSoundTemplates = {}
KillSoundTemplates = {}
DeathSoundTemplates = {}
function PrepareHitSounds()
    local assets = {CustomHitSound1Asset, CustomHitSound2Asset, CustomHitSound3Asset}
    for i, soundId in ipairs(assets) do
        if soundId and not HitSoundTemplates[i] then
            local template = Instance.new("Sound")
            template.Name = "ApexHitSoundTemplate" .. i
            template.SoundId = soundId
            -- Keep the embedded source at its original 1.00 gain; the slider
            -- scales only the temporary playback clone.
            template.Volume = 1.00
            template.Parent = workspace
            HitSoundTemplates[i] = template
        end
    end
    local killAssets = {CustomKillSound1Asset, CustomKillSound2Asset, CustomKillSound3Asset}
    for i, soundId in ipairs(killAssets) do
        if soundId and not KillSoundTemplates[i] then
            local template = Instance.new("Sound")
            template.Name = "ApexKillSoundTemplate" .. i
            template.SoundId = soundId
            template.Volume = 1
            template.Parent = workspace
            KillSoundTemplates[i] = template
        end
    end
    local deathAssets = {CustomDeathSound1Asset, CustomDeathSound2Asset, CustomDeathSound3Asset}
    for i, soundId in ipairs(deathAssets) do
        if soundId and not DeathSoundTemplates[i] then
            local template = Instance.new("Sound")
            template.Name = "ApexDeathSoundTemplate" .. i
            template.SoundId = soundId
            template.Volume = 1
            template.Parent = workspace
            DeathSoundTemplates[i] = template
        end
    end
    local preloadList = {}
    for _, template in pairs(HitSoundTemplates) do table.insert(preloadList, template) end
    for _, template in pairs(KillSoundTemplates) do table.insert(preloadList, template) end
    for _, template in pairs(DeathSoundTemplates) do table.insert(preloadList, template) end
    if #preloadList > 0 then pcall(function() ContentProvider:PreloadAsync(preloadList) end) end
end
function PlaySelectedHitSound()
    local choice = Config.HitSoundChoice or 1
    if choice == 4 then
        local id = tostring(Config.HitSoundCustomId or ""):match("%d+")
        if not id or id == "0" then return end
        local sound = Instance.new("Sound")
        sound.Name = "ApexCustomHitSound"
        sound.SoundId = "rbxassetid://" .. id
        sound.Volume = math.clamp((Config.HitSoundVolume or 100) / 100, 0, 1) * 3
        sound.Parent = workspace
        sound.Ended:Connect(function() sound:Destroy() end)
        pcall(function() sound:Play() end)
        task.delay(8, function() if sound and sound.Parent then sound:Destroy() end end)
        return
    end
    choice = math.clamp(choice, 1, 3)
    local template = HitSoundTemplates[choice]
    if not template then
        PrepareHitSounds()
        template = HitSoundTemplates[choice]
    end
    if not template then return end
    -- Clone an already preloaded template so playback starts without asset-loading delay.
    local sound = template:Clone()
    sound.Name = "ApexHitSound"
    sound.Volume = math.clamp((Config.HitSoundVolume or 100) / 100, 0, 1) * 3
    sound.Parent = workspace
    sound.TimePosition = 0
    sound.Ended:Connect(function() sound:Destroy() end)
    pcall(function() sound:Play() end)
    task.delay(5, function() if sound and sound.Parent then sound:Destroy() end end)
end
function PlaySelectedKillSound()
    local choice = Config.KillSoundChoice or 1
    if choice == 4 then
        local id = tostring(Config.KillSoundCustomId or ""):match("%d+")
        if not id or id == "0" then return end
        local sound = Instance.new("Sound")
        sound.Name = "ApexCustomKillSound"
        sound.SoundId = "rbxassetid://" .. id
        sound.Volume = math.clamp((Config.KillSoundVolume or 100) / 100, 0, 1) * 3
        sound.Parent = workspace
        sound.Ended:Connect(function() sound:Destroy() end)
        pcall(function() sound:Play() end)
        task.delay(12, function() if sound and sound.Parent then sound:Destroy() end end)
        return
    end
    choice = math.clamp(choice, 1, 3)
    local template = KillSoundTemplates[choice]
    if not template then
        PrepareHitSounds()
        template = KillSoundTemplates[choice]
    end
    if not template then return end
    local sound = template:Clone()
    sound.Name = "ApexKillSound"
    sound.Volume = math.clamp((Config.KillSoundVolume or 100) / 100, 0, 1) * 3
    sound.Parent = workspace
    sound.TimePosition = 0
    sound.Ended:Connect(function() sound:Destroy() end)
    pcall(function() sound:Play() end)
    task.delay(10, function() if sound and sound.Parent then sound:Destroy() end end)
end
function PlaySelectedDeathSound()
    local choice = Config.DeathSoundChoice or 1
    if choice == 4 then
        local id = tostring(Config.DeathSoundCustomId or ""):match("%d+")
        if not id or id == "0" then return end
        if ActiveDeathSound and ActiveDeathSound.Parent then ActiveDeathSound:Destroy() end
        local sound = Instance.new("Sound")
        sound.Name = "ApexCustomDeathSound"
        sound.SoundId = "rbxassetid://" .. id
        sound.Volume = math.clamp((Config.DeathSoundVolume or 100) / 100, 0, 1) * 3
        sound.Looped = false
        sound.Parent = workspace
        ActiveDeathSound = sound
        sound.Ended:Connect(function() if ActiveDeathSound == sound then ActiveDeathSound = nil end; sound:Destroy() end)
        pcall(function() sound:Play() end)
        task.delay(15, function() if ActiveDeathSound == sound then ActiveDeathSound = nil end; if sound and sound.Parent then sound:Destroy() end end)
        return
    end
    choice = math.clamp(choice, 1, 3)
    local template = DeathSoundTemplates[choice]
    if not template then
        PrepareHitSounds()
        template = DeathSoundTemplates[choice]
    end
    if not template then return end
    if ActiveDeathSound and ActiveDeathSound.Parent then ActiveDeathSound:Destroy() end
    local sound = template:Clone()
    sound.Name = "ApexDeathSound"
    sound.Volume = math.clamp((Config.DeathSoundVolume or 100) / 100, 0, 1) * 3
    sound.Looped = false
    sound.Parent = workspace
    sound.TimePosition = 0
    ActiveDeathSound = sound
    sound.Ended:Connect(function()
        if ActiveDeathSound == sound then ActiveDeathSound = nil end
        sound:Destroy()
    end)
    pcall(function() sound:Play() end)
    task.delay(15, function()
        if ActiveDeathSound == sound then ActiveDeathSound = nil end
        if sound and sound.Parent then sound:Destroy() end
    end)
end
function IsTargetInsideHitSoundRange(targetHumanoid)
    local now = os.clock()
    local abilityActive = now <= HitSoundAbilityUntil
    if now > HitSoundLocalAttackUntil and not abilityActive then return false end
    if HitSoundAttackSoundPlayed and not abilityActive then return false end
    local localCharacter = LocalPlayer.Character
    local targetCharacter = targetHumanoid and targetHumanoid.Parent
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")
    if not localRoot or not targetRoot then return false end
    local offset = targetRoot.Position - localRoot.Position
    if offset.Magnitude > 30 then return false end
    local flatOffset = Vector3.new(offset.X, 0, offset.Z)
    if flatOffset.Magnitude < 0.01 then return true end
    local flatLook = Vector3.new(localRoot.CFrame.LookVector.X, 0, localRoot.CFrame.LookVector.Z)
    return flatLook.Magnitude > 0 and flatLook.Unit:Dot(flatOffset.Unit) > 0.15
end
function AttachHitSoundHumanoid(player, humanoid)
    if not humanoid then return end
    if player and (player == LocalPlayer or IsCheatFriend(player)) then return end
    if HitSoundHealthConns[humanoid] then return end
    HitSoundLastHealth[humanoid] = humanoid.Health
    HitSoundHealthConns[humanoid] = humanoid.HealthChanged:Connect(function(newHealth)
        local previous = HitSoundLastHealth[humanoid] or newHealth
        HitSoundLastHealth[humanoid] = newHealth
        if (Config.HitSoundEnabled or Config.KillSoundEnabled) and newHealth < previous then
            -- Never react unless this client has just attacked and the target
            -- is in front within 30 studs.
            if IsTargetInsideHitSoundRange(humanoid) then
                local now = os.clock()
                if now - HitSoundLastPlayback >= 0.06 then
                    HitSoundLastPlayback = now
                    if now > HitSoundAbilityUntil then HitSoundAttackSoundPlayed = true end
                    if newHealth <= 0 and previous > 0 and Config.KillSoundEnabled then
                        PlaySelectedKillSound()
                    elseif Config.HitSoundEnabled then
                        PlaySelectedHitSound()
                    end
                end
            end
        end
    end)
end
function ScanHitSoundTargets()
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and not IsCheatFriend(player) then
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if humanoid then AttachHitSoundHumanoid(player, humanoid) end
        end
    end
    -- Include NPCs and training dummies that have a Humanoid but no Player.
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Humanoid") then
            local model = object.Parent
            local owner = model and Players:GetPlayerFromCharacter(model)
            if not owner and model ~= LocalPlayer.Character then
                AttachHitSoundHumanoid(nil, object)
            end
        end
    end
    for humanoid, connection in pairs(HitSoundHealthConns) do
        if not humanoid.Parent then
            connection:Disconnect()
            HitSoundHealthConns[humanoid] = nil
            HitSoundLastHealth[humanoid] = nil
        end
    end
end
function StopHitSound()
    if HitSoundWatchConn then HitSoundWatchConn:Disconnect(); HitSoundWatchConn = nil end
    if HitSoundInputConn then HitSoundInputConn:Disconnect(); HitSoundInputConn = nil end
    HitSoundLocalAttackUntil = 0
    HitSoundAttackSoundPlayed = false
    HitSoundNextHeldArm = 0
    HitSoundAbilityUntil = 0
    HitSoundLastPlayback = -math.huge
    for humanoid, connection in pairs(HitSoundHealthConns) do
        pcall(function() connection:Disconnect() end)
        HitSoundHealthConns[humanoid] = nil
        HitSoundLastHealth[humanoid] = nil
    end
end
function StartHitSound()
    StopHitSound()
    ScanHitSoundTargets()
    HitSoundInputConn = UIS.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or not (Config.HitSoundEnabled or Config.KillSoundEnabled) then return end
        local now = os.clock()
        local isAbility = input.KeyCode == Enum.KeyCode.One or input.KeyCode == Enum.KeyCode.Two
            or input.KeyCode == Enum.KeyCode.Three or input.KeyCode == Enum.KeyCode.Four
        if isAbility then
            -- Multi-hit abilities may continue dealing damage for several seconds.
            HitSoundAbilityUntil = now + 4.5
            HitSoundLocalAttackUntil = HitSoundAbilityUntil
            HitSoundAttackSoundPlayed = false
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            HitSoundAttackSoundPlayed = false
            HitSoundLocalAttackUntil = now + 0.75
            HitSoundNextHeldArm = now + 0.20
        end
    end)
    local elapsed = 0
    HitSoundWatchConn = RunService.Heartbeat:Connect(function(dt)
        if not ScriptAlive or not (Config.HitSoundEnabled or Config.KillSoundEnabled) then return end
        local now = os.clock()
        if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
            if now >= HitSoundNextHeldArm then
                HitSoundNextHeldArm = now + 0.20
                HitSoundLocalAttackUntil = now + 0.35
                HitSoundAttackSoundPlayed = false
            end
        else
            HitSoundNextHeldArm = 0
        end
        elapsed = elapsed + dt
        if elapsed >= 2 then
            elapsed = 0
            ScanHitSoundTargets()
        end
    end)
end
function DestroyHitSoundTemplates()
    for i, template in pairs(HitSoundTemplates) do
        if template then template:Destroy() end
        HitSoundTemplates[i] = nil
    end
    for i, template in pairs(KillSoundTemplates) do
        if template then template:Destroy() end
        KillSoundTemplates[i] = nil
    end
    for i, template in pairs(DeathSoundTemplates) do
        if template then template:Destroy() end
        DeathSoundTemplates[i] = nil
    end
end
DeathSoundDiedConn = nil
DeathSoundCharacterConn = nil
DeathSoundPlayedForCharacter = false
ActiveDeathSound = nil
function AttachDeathSoundCharacter(character)
    if DeathSoundDiedConn then DeathSoundDiedConn:Disconnect(); DeathSoundDiedConn = nil end
    DeathSoundPlayedForCharacter = false
    local humanoid = character and character:FindFirstChildOfClass("Humanoid") or character and character:WaitForChild("Humanoid", 10)
    if humanoid then
        DeathSoundDiedConn = humanoid.Died:Connect(function()
            if Config.DeathSoundEnabled and not DeathSoundPlayedForCharacter then
                DeathSoundPlayedForCharacter = true
                PlaySelectedDeathSound()
            end
        end)
    end
end
function StopDeathSound()
    if DeathSoundDiedConn then DeathSoundDiedConn:Disconnect(); DeathSoundDiedConn = nil end
    if DeathSoundCharacterConn then DeathSoundCharacterConn:Disconnect(); DeathSoundCharacterConn = nil end
    DeathSoundPlayedForCharacter = false
    if ActiveDeathSound and ActiveDeathSound.Parent then ActiveDeathSound:Destroy() end
    ActiveDeathSound = nil
end
function StartDeathSound()
    StopDeathSound()
    Config.DeathSoundEnabled = true
    AttachDeathSoundCharacter(LocalPlayer.Character)
    DeathSoundCharacterConn = LocalPlayer.CharacterAdded:Connect(function(character)
        AttachDeathSoundCharacter(character)
    end)
end
task.spawn(PrepareHitSounds)
-- White on-screen circle that visualizes the angular FOV selected in the AIM tab.
FOVCircle = nil
FOVCircleConn = nil
function StopDrawFOV()
    if FOVCircleConn then FOVCircleConn:Disconnect(); FOVCircleConn = nil end
    if FOVCircle then
        pcall(function() FOVCircle:Remove() end)
        FOVCircle = nil
    end
end
function StartDrawFOV()
    StopDrawFOV()
    Config.DrawFOV = true
    FOVCircle = Drawing.new("Circle")
    FOVCircle.Visible = true
    FOVCircle.Filled = false
    FOVCircle.Color = Color3.fromRGB(255, 255, 255)
    FOVCircle.Transparency = 1
    FOVCircle.Thickness = 1.5
    FOVCircle.NumSides = 96
    FOVCircleConn = RunService.RenderStepped:Connect(function()
        if not ScriptAlive or not Config.DrawFOV or not FOVCircle then
            StopDrawFOV()
            return
        end
        local cam = workspace.CurrentCamera
        if not cam then return end
        local viewport = cam.ViewportSize
        FOVCircle.Position = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5)
        -- Convert the aim angle to screen pixels using the camera's vertical FOV.
        local aimHalf = math.rad(math.clamp(Config.AimFOV or 0, 0, 179) * 0.5)
        local cameraHalf = math.rad(math.clamp(cam.FieldOfView, 1, 179) * 0.5)
        local focalLength = (viewport.Y * 0.5) / math.tan(cameraHalf)
        FOVCircle.Radius = math.max(0, math.tan(aimHalf) * focalLength)
        FOVCircle.Visible = Config.DrawFOV and Config.AimFOV > 0
    end)
end
