do -- Hitbox dropdown and Aim Assistant bind
    -- Keep the bind button created by CreateToggle and place it before the switch.
    local oldBind = BindButtons["Aim Assistant"]
    if oldBind then
        oldBind.Size = UDim2.new(0, 34, 0, 20)
        oldBind.Position = UDim2.new(1, -154, 0.5, -10)
        oldBind.ZIndex = 8
    end
    -- Keep the value close to the on/off switch and reserve the far-right slot for the arrow.
    local aimValue = ToggleValueLabels["Aim Assistant"]
    local aimSwitch
    for _, child in ipairs(AimAssistantCard:GetChildren()) do
        if child:IsA("TextButton") and child.Text == "" and child.Size.X.Offset == 46 then
            aimSwitch = child
            break
        end
    end
    if aimSwitch then aimSwitch.Position = UDim2.new(1, -116, 0.5, -13) end
    if aimValue then
        aimValue.Size = UDim2.new(0, 30, 0, 18)
        aimValue.Position = UDim2.new(1, -66, 0.5, -9) -- 4 px after the switch
        aimValue.TextXAlignment = Enum.TextXAlignment.Center
    end
    local ArrowBtn = Instance.new("TextButton")
    ArrowBtn.Name = "HitboxArrow"
    ArrowBtn.Size = UDim2.new(0, 28, 0, 24)
    ArrowBtn.Position = UDim2.new(1, -34, 0.5, -12)
    ArrowBtn.BackgroundColor3 = C.Track
    ArrowBtn.BorderSizePixel = 0
    ArrowBtn.AutoButtonColor = false
    ArrowBtn.Text = "▼"
    ArrowBtn.TextColor3 = C.TDim
    ArrowBtn.Font = Enum.Font.GothamBold
    ArrowBtn.TextSize = 11
    ArrowBtn.TextStrokeTransparency = 1
    ArrowBtn.ZIndex = 8
    ArrowBtn.Parent = AimAssistantCard
    Instance.new("UICorner", ArrowBtn).CornerRadius = UDim.new(0, 6)
    local Menu = Instance.new("Frame")
    Menu.Name = "HitboxMenu"
    Menu.Size = UDim2.new(0, 138, 0, 0)
    -- The AIM card is at the top, so the foreground menu expands below it.
    Menu.AnchorPoint = Vector2.new(0, 0)
    Menu.Position = UDim2.new(1, -144, 1, 4)
    Menu.BackgroundColor3 = C.Sidebar
    Menu.BackgroundTransparency = 1
    Menu.BorderSizePixel = 0
    Menu.ClipsDescendants = true
    Menu.Visible = false
    Menu.ZIndex = 50
    Menu.Parent = AimAssistantCard
    Instance.new("UICorner", Menu).CornerRadius = UDim.new(0, 8)
    local menuStroke = MakeStroke(Menu, C.Border, 1)
    menuStroke.Transparency = 1
    Config.AimHitboxes = Config.AimHitboxes or {Head=true, Torso=false, Arms=false, Legs=false, Neck=false}
    local options = {
        {label = "Head", key = "Head"},
        {label = "Torso", key = "Torso"},
        {label = "Arms", key = "Arms"},
        {label = "Legs", key = "Legs"},
        {label = "Neck", key = "Neck"},
    }
    local optionButtons = {}
    local function RefreshSelections()
        for j, btn in ipairs(optionButtons) do
            local selected = Config.AimHitboxes[options[j].key] == true
            btn.BackgroundColor3 = selected and C.CardOn or C.Card
            btn.TextColor3 = selected and C.TOn or C.TMain
            btn.Text = (selected and "✓  " or "    ") .. options[j].label
        end
    end
    for i, option in ipairs(options) do
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(1, -8, 0, 28)
        b.Position = UDim2.new(0, 4, 0, 4 + (i - 1) * 30)
        b.BackgroundColor3 = C.Card
        b.BackgroundTransparency = 1
        b.BorderSizePixel = 0
        b.AutoButtonColor = false
        b.Text = option.label
        b.TextColor3 = C.TMain
        b.TextTransparency = 1
        b.TextXAlignment = Enum.TextXAlignment.Left
        b.Font = Enum.Font.GothamBold
        b.TextSize = 11
        b.TextStrokeTransparency = 1
        b.ZIndex = 51
        b.Parent = Menu
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        optionButtons[i] = b
        b.MouseButton1Click:Connect(function()
            Config.AimHitboxes[option.key] = not Config.AimHitboxes[option.key]
            RefreshSelections()
        end)
    end
    RefreshSelections()
    local opened = false
    local anim = TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local function SetOpen(state)
        opened = state
        ArrowBtn.Text = opened and "▲" or "▼"
        ArrowBtn.TextColor3 = opened and C.TOn or C.TDim
        if opened then
            -- Raise the complete dropdown above the surrounding controls.
            AimAssistantCard.ZIndex = 40
            ArrowBtn.ZIndex = 52
            Menu.Visible = true
            TweenService:Create(Menu, anim, {Size = UDim2.new(0, 138, 0, 156), BackgroundTransparency = 0}):Play()
            TweenService:Create(menuStroke, anim, {Transparency = 0}):Play()
            for _, b in ipairs(optionButtons) do
                TweenService:Create(b, anim, {BackgroundTransparency = 0, TextTransparency = 0}):Play()
            end
        else
            TweenService:Create(Menu, anim, {Size = UDim2.new(0, 138, 0, 0), BackgroundTransparency = 1}):Play()
            TweenService:Create(menuStroke, anim, {Transparency = 1}):Play()
            for _, b in ipairs(optionButtons) do
                TweenService:Create(b, anim, {BackgroundTransparency = 1, TextTransparency = 1}):Play()
            end
            task.delay(0.22, function()
                if not opened then
                    Menu.Visible = false
                    AimAssistantCard.ZIndex = 1
                    ArrowBtn.ZIndex = 8
                end
            end)
        end
    end
    ArrowBtn.MouseButton1Click:Connect(function() SetOpen(not opened) end)
end
