APEX_MIRAGE_RAW_URL = "https://raw.githubusercontent.com/scripterbbn/Apex-Mirage/main/Apex%20Mirage.lua"
function QueueApexAfterTeleport()
    local env = getgenv and getgenv() or _G
    local queueTeleport = (env and (env.queue_on_teleport or env.queueonteleport or env.queue_on_tp))
        or queue_on_teleport or queueonteleport
        or (syn and syn.queue_on_teleport)
        or (fluxus and fluxus.queue_on_teleport)
    if type(queueTeleport) ~= "function" then
        pcall(function() StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text="Teleport queue is not supported by this executor", Duration=4}) end)
        return false
    end
    local loader = string.format([[
repeat task.wait(0.25) until game:IsLoaded()
task.wait(3)
for attempt = 1, 10 do
    local ok, source = pcall(function()
        return game:HttpGet(%q, true)
    end)
    if ok and source and #source > 0 then
        local chunk = loadstring(source)
        if chunk then
            local ran = pcall(chunk)
            if ran then break end
        end
    end
    task.wait(2)
end
]], APEX_MIRAGE_RAW_URL)
    local queuedSource = loader
    if writefile and readfile then
        local loaderPath = APEX_MIRAGE_DIR .. "/rejoin_loader.lua"
        local wrote = pcall(writefile, loaderPath, loader)
        if wrote then
            queuedSource = 'loadstring(readfile("' .. loaderPath .. '"))()'
        end
    end
    local callOk, queueResult = pcall(queueTeleport, queuedSource)
    local ok = callOk and queueResult ~= false
    pcall(function()
        StarterGui:SetCore("SendNotification", {
            Title="Apex Mirage",
            Text=ok and "Auto-execute queued" or "Failed to queue auto-execute",
            Duration=3,
        })
    end)
    return ok
end
CreateAction("Rejoin", Pages.SETTINGS, 60, C.Blue, function()
    QueueApexAfterTeleport()
    task.wait(0.5)
    TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
end)
CreateAction("Server Hop", Pages.SETTINGS, 114, C.Yellow, function()
    task.spawn(function()
        local function NotifyHop(text)
            pcall(function()
                StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text=text, Duration=3})
            end)
        end
        -- Executors commonly block HttpService:GetAsync, so try their request API
        -- first and retain game:HttpGet as a compatible fallback.
        local function ReadUrl(url)
            local requestFn = (syn and syn.request) or http_request or request
            if requestFn then
                local ok, response = pcall(requestFn, {Url=url, Method="GET"})
                if ok and response then
                    local status = tonumber(response.StatusCode or response.Status) or 200
                    local body = response.Body or response.body
                    if status >= 200 and status < 300 and body then return body end
                end
            end
            local ok, body = pcall(function() return game:HttpGet(url) end)
            if ok and body then return body end
            local okService, serviceBody = pcall(function() return HttpService:GetAsync(url) end)
            if okService then return serviceBody end
            return nil
        end
        NotifyHop("Searching for another server...")
        local cursor = nil
        local candidates = {}
        -- Check several pages instead of failing when the first page only contains
        -- the current or full servers.
        for _ = 1, 5 do
            local url = "https://games.roblox.com/v1/games/" .. game.PlaceId
                .. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100"
            if cursor and cursor ~= "" then
                url = url .. "&cursor=" .. HttpService:UrlEncode(cursor)
            end
            local body = ReadUrl(url)
            if not body then break end
            local okDecode, page = pcall(function() return HttpService:JSONDecode(body) end)
            if not okDecode or not page then break end
            for _, server in ipairs(page.data or {}) do
                if server.id and server.id ~= game.JobId
                    and tonumber(server.playing or 0) < tonumber(server.maxPlayers or 0) then
                    table.insert(candidates, server)
                end
            end
            if #candidates > 0 then break end
            cursor = page.nextPageCursor
            if not cursor then break end
        end
        if #candidates == 0 then
            NotifyHop("No available server found")
            return
        end
        -- Pick a random valid server so repeated hops do not keep selecting the same one.
        local target = candidates[math.random(1, #candidates)]
        QueueApexAfterTeleport()
        local okTeleport, teleportError = pcall(function()
            TeleportService:TeleportToPlaceInstance(game.PlaceId, target.id, LocalPlayer)
        end)
        if not okTeleport then
            NotifyHop("Server Hop Failed: " .. tostring(teleportError))
        end
    end)
end)
