CreateAction("Unload", Pages.SETTINGS, 168, C.Red, function()
    ScriptAlive = false
    for K,_ in pairs(Config) do Config[K] = false end
    for K,_ in pairs(ESPConfig) do ESPConfig[K] = false end
    StopFly()
    StopBlink()
    StopHitbox()
    StopInvisibility()
    StopFreeCam()
    StopAim()
    StopHitSound()
    StopDeathSound()
    DestroyHitSoundTemplates()
    StopDrawFOV()
    StopItemESP()
    StopInstantInteraction()
    StopNoVoid()
    StopOrbit()
    StopAntiFling()
    StopEmote()
    RestoreFullbright()
    RestoreNoFog()
    RemoveAllSkeletons()
    local Ch = LocalPlayer.Character
    if Ch then
        local Hu = Ch:FindFirstChildOfClass("Humanoid")
        if Hu then Hu.WalkSpeed = 16; Hu.JumpPower = 50 end
    end
    for P,_ in pairs(EspObjects) do RemoveESP(P) end
    EspObjects = {}
    for _, S in ipairs(AllSliders) do S.Dragging = false end
    for _, Co in ipairs(Connections) do pcall(function() Co:Disconnect() end) end
    Connections = {}
    task.wait(0.2)
    if SG then SG:Destroy() end
    pcall(function() StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text="Script Unloaded", Duration=3}) end)
end)
-- ═══════ CONFIG SYSTEM ═══════
local CONFIG_DIR = APEX_MIRAGE_CONFIG_DIR
local ApplyLoadedConfig
AUTOLOAD_CONFIG_FILE = APEX_MIRAGE_DIR .. "/autoload_config.json"
AutoloadConfigState = {Enabled=false, Name=""}
function LoadAutoloadConfigState()
    if not readfile or not isfile or not isfile(AUTOLOAD_CONFIG_FILE) then return end
    local okRead, content = pcall(readfile, AUTOLOAD_CONFIG_FILE)
    if not okRead or not content then return end
    local okDecode, data = pcall(HttpService.JSONDecode, HttpService, content)
    if okDecode and type(data) == "table" then
        AutoloadConfigState.Enabled = data.Enabled == true
        AutoloadConfigState.Name = tostring(data.Name or "")
    end
end
function SaveAutoloadConfigState()
    if not writefile then return end
    local okEncode, content = pcall(HttpService.JSONEncode, HttpService, AutoloadConfigState)
    if okEncode then pcall(writefile, AUTOLOAD_CONFIG_FILE, content) end
end
LoadAutoloadConfigState()
local function ConfigNotify(msg)
    pcall(function()
        StarterGui:SetCore("SendNotification", {Title="Apex Mirage", Text=msg, Duration=3})
    end)
end
local function HasFileAPI()
    return writefile and readfile and isfile and isfolder and makefolder and listfiles and delfile
end
local function EnsureConfigDir()
    if not HasFileAPI() then return false end
    if not isfolder(CONFIG_DIR) then
        local ok = pcall(makefolder, CONFIG_DIR)
        if not ok then return false end
    end
    return true
end
local function SerializeColors()
    local out = {}
    for key, col in pairs(ESPColors) do
        out[key] = {
            math.floor(col.R * 255 + 0.5),
            math.floor(col.G * 255 + 0.5),
            math.floor(col.B * 255 + 0.5),
        }
    end
    return out
end
local function DeserializeColors(data)
    if not data then return end
    for key, rgb in pairs(data) do
        if ESPColors[key] and type(rgb) == "table" and #rgb >= 3 then
            ESPColors[key] = Color3.fromRGB(rgb[1], rgb[2], rgb[3])
        end
    end
end
local function SaveConfig(name)
    if not HasFileAPI() then
        ConfigNotify("Config API not available")
        return false
    end
    if not EnsureConfigDir() then
        ConfigNotify("Failed to create config folder")
        return false
    end
    name = tostring(name or ""):gsub("[^%w%-_]", "")
    if name == "" then
        ConfigNotify("Enter a config name")
        return false
    end
    local data = {
        version = 1,
        config = Config,
        esp = ESPConfig,
        colors = SerializeColors(),
        binds = {},
    }
    for action, bind in pairs(Binds) do
        if typeof(bind) == "EnumItem" then
            data.binds[action] = {Type = "Key", Value = bind.Value, Name = bind.Name}
        elseif type(bind) == "table" and bind.IsMouseBind then
            data.binds[action] = {IsMouseBind = true, MBStr = bind.MBStr, Name = bind.Name}
        end
    end
    local okJson, json = pcall(HttpService.JSONEncode, HttpService, data)
    if not okJson then
        ConfigNotify("Failed to encode config")
        return false
    end
    local filePath = CONFIG_DIR .. "/" .. name .. ".cfg"
    local okWrite = pcall(writefile, filePath, json)
    if okWrite then
        ConfigNotify('Saved "' .. name .. '"')
        if RefreshConfigListUI then task.defer(RefreshConfigListUI) end
        return true
    end
    ConfigNotify("Save failed")
    return false
end
local function LoadConfig(name)
    if not HasFileAPI() then
        ConfigNotify("Config API not available")
        return false
    end
    name = tostring(name or ""):gsub("[^%w%-_]", "")
    if name == "" then
        ConfigNotify("Enter a config name")
        return false
    end
    local filePath = CONFIG_DIR .. "/" .. name .. ".cfg"
    if not isfile(filePath) then
        ConfigNotify('Config "' .. name .. '" not found')
        return false
    end
    local okRead, content = pcall(readfile, filePath)
    if not okRead or not content then
        ConfigNotify("Failed to read config")
        return false
    end
    local okJson, data = pcall(HttpService.JSONDecode, HttpService, content)
    if not okJson or not data then
        ConfigNotify("Invalid config file")
        return false
    end
    -- Start from clean defaults instead of merging into the currently active state.
    -- Any function absent from the loaded file therefore becomes disabled.
    for key in pairs(Config) do Config[key] = nil end
    for key, value in pairs(DefaultConfig) do Config[key] = DeepCopy(value) end
    for key in pairs(ESPConfig) do ESPConfig[key] = nil end
    for key, value in pairs(DefaultESPConfig) do ESPConfig[key] = DeepCopy(value) end
    if data.config then
        for k, v in pairs(data.config) do Config[k] = v end
    end
    if data.esp then
        for k, v in pairs(data.esp) do ESPConfig[k] = v end
    end
    DeserializeColors(data.colors)
    if data.binds then
        for action, b in pairs(data.binds) do
            if b.Type == "Key" then
                for _, kc in pairs(Enum.KeyCode:GetEnumItems()) do
                    if kc.Value == b.Value then
                        Binds[action] = kc
                        break
                    end
                end
            elseif b.IsMouseBind then
                if b.UIT then
                    Binds[action] = {IsMouseBind = true, MBStr = b.MBStr, Name = b.Name}
                end
            end
            local btn = BindButtons[action]
            if btn then
                if Binds[action] then
                    btn.Text = Binds[action].Name
                    btn.TextColor3 = C.TDim
                else
                    btn.Text = "..."
                    btn.TextColor3 = C.TDim
                end
            end
        end
    end
    if ApplyLoadedConfig then ApplyLoadedConfig() end
    ConfigNotify('Loaded "' .. name .. '"')
    return true
end
local function DeleteConfig(name)
    if not HasFileAPI() then
        ConfigNotify("Config API not available")
        return false
    end
    name = tostring(name or ""):gsub("[^%w%-_]", "")
    if name == "" then
        ConfigNotify("Enter a config name")
        return false
    end
    local filePath = CONFIG_DIR .. "/" .. name .. ".cfg"
    if not isfile(filePath) then
        ConfigNotify('Config "' .. name .. '" not found')
        return false
    end
    local ok = pcall(delfile, filePath)
    if ok then
        ConfigNotify('Deleted "' .. name .. '"')
        if AutoloadConfigState.Name == name then
            AutoloadConfigState.Name = ""
            AutoloadConfigState.Enabled = false
            SaveAutoloadConfigState()
            if RefreshAutoloadConfigUI then RefreshAutoloadConfigUI() end
        end
        if RefreshConfigListUI then task.defer(RefreshConfigListUI) end
        return true
    end
    ConfigNotify("Delete failed")
    return false
end
local function ListConfigs()
    if not HasFileAPI() then return {} end
    pcall(EnsureConfigDir)
    local files = {}
    pcall(function() files = listfiles(CONFIG_DIR) end)
    local result = {}
    for _, path in pairs(files) do
        local cfgName = path:gsub(CONFIG_DIR .. "/", ""):gsub("%.cfg$", "")
        if cfgName ~= "" then table.insert(result, cfgName) end
    end
    table.sort(result)
    return result
end
