-- Mouse binds use tostring(UserInputType) as key -- safe in all executors
-- Keyboard binds -- original handler, untouched
table.insert(Connections, UIS.InputBegan:Connect(function(Input, GP)
    if not ScriptAlive then return end
    -- Insert must work even while a TextBox is focused and Roblox marks input
    -- as game-processed.
    if Input.KeyCode == Enum.KeyCode.Insert then
        if IsLoading then return end
        local focusedTextBox = UIS:GetFocusedTextBox()
        if focusedTextBox then focusedTextBox:ReleaseFocus() end
        if SearchResultsFrame then SearchResultsFrame.Visible = false end
        MF.Visible = not MF.Visible
        if MF.Visible then
            UIS.MouseIconEnabled = true
            UIS.MouseBehavior = Enum.MouseBehavior.Default
        end
        return
    end
    if ListeningBind then
        if Input.UserInputType == Enum.UserInputType.Keyboard then
            if Input.KeyCode == Enum.KeyCode.Escape then
                Binds[ListeningBind] = nil
                local B = BindButtons[ListeningBind]
                if B then B.Text = "..." B.TextColor3 = C.TDim end
            else
                Binds[ListeningBind] = Input.KeyCode
                local B = BindButtons[ListeningBind]
                if B then B.Text = Input.KeyCode.Name B.TextColor3 = C.TDim end
            end
            ListeningBind = nil
        end
        return
    end
    if GP then return end
    if Input.UserInputType == Enum.UserInputType.Keyboard then
        for Feature, KeyCode in pairs(Binds) do
            if Input.KeyCode == KeyCode and ToggleFuncs[Feature] then
                ToggleFuncs[Feature]()
            end
        end
    end
end))
-- Mouse button binds -- separate handler, all logic inside callback (errors caught by Roblox)
table.insert(Connections, UIS.InputBegan:Connect(function(Input, GP)
    if not ScriptAlive then return end
    -- tostring(UserInputType) gives e.g. "Enum.UserInputType.MouseButton1" -- no .Value needed
    local uitStr = tostring(Input.UserInputType)
    local mbNames = {
        ["Enum.UserInputType.MouseButton1"] = "M1",
        ["Enum.UserInputType.MouseButton2"] = "M2",
        ["Enum.UserInputType.MouseButton3"] = "M3",
        ["Enum.UserInputType.MouseButton4"] = "M4",
        ["Enum.UserInputType.MouseButton5"] = "M5",
    }
    local mbName = mbNames[uitStr]
    if not mbName then return end
    if ListeningBind then
        Binds[ListeningBind] = {IsMouseBind = true, MBStr = uitStr, Name = mbName}
        local B = BindButtons[ListeningBind]
        if B then B.Text = mbName; B.TextColor3 = C.TDim end
        ListeningBind = nil
        return
    end
    if GP then return end
    for Feature, bind in pairs(Binds) do
        if type(bind) == "table" and bind.IsMouseBind and bind.MBStr == uitStr and ToggleFuncs[Feature] then
            ToggleFuncs[Feature]()
        end
    end
end))
-- SEPARATE mouse button bind handler
table.insert(Connections, UIS.InputBegan:Connect(function(Input, GP)
    if not ScriptAlive then return end
    local mbName = MB_NAMES[Input.UserInputType.Value]
    if not mbName then return end  -- not a mouse button
    if ListeningBind then
        -- Capture: set this mouse button as the bind
        Binds[ListeningBind] = {IsMouseBind = true, UITValue = Input.UserInputType.Value, Name = mbName}
        local B = BindButtons[ListeningBind]
        if B then B.Text = mbName; B.TextColor3 = C.TDim end
        ListeningBind = nil
        return
    end
    if GP then return end
    -- Fire: execute any toggle bound to this mouse button
    local uitv = Input.UserInputType.Value
    for Feature, bind in pairs(Binds) do
        if type(bind) == "table" and bind.IsMouseBind and bind.UITValue == uitv and ToggleFuncs[Feature] then
            ToggleFuncs[Feature]()
        end
    end
end))
