--         ESP SYSTEM
-- ═══════════════════════════════════════════════
-- Stable upright 2D character box. Its width is derived from screen height,
-- so rotating the camera around a character cannot widen the box.
local function GetScreenBox(char)
    local cam = workspace.CurrentCamera
    if not cam then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    local head = char:FindFirstChild("Head")
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not root or not head or not humanoid or humanoid.Health <= 0 then return nil end
    -- Ignore broken/streamed rigs instead of drawing a box across the screen.
    if (head.Position - root.Position).Magnitude > 15 then return nil end
    -- Fixed body points prevent accessories, tools, effects and enlarged hitboxes
    -- from changing the dimensions of the ESP box.
    local topWorld = head.Position + Vector3.new(0, 0.75, 0)
    local bottomWorld = root.Position - Vector3.new(0, 3, 0)
    local top = cam:WorldToViewportPoint(topWorld)
    local bottom = cam:WorldToViewportPoint(bottomWorld)
    local center = cam:WorldToViewportPoint(root.Position)
    if top.Z <= 0 or bottom.Z <= 0 or center.Z <= 0 then return nil end
    local height = math.abs(bottom.Y - top.Y)
    if height < 2 or height > cam.ViewportSize.Y * 1.5 then return nil end
    local width = height * 0.55
    local x = center.X - width * 0.5
    local y = math.min(top.Y, bottom.Y)
    return x, y, width, height
end
local function RemoveESP(Player)
    if not EspObjects[Player] then return end
    local Data = EspObjects[Player]
    if Data.UpdateConn then Data.UpdateConn:Disconnect(); Data.UpdateConn = nil end
    local drawings = {"Box","NameLabel","DistLabel","HPBg","HPFill"}
    for _, key in ipairs(drawings) do
        if Data[key] then pcall(function() Data[key]:Remove() end) end
    end
    if Data.BoxCorners then
        for _, line in ipairs(Data.BoxCorners) do pcall(function() line:Remove() end) end
    end
    if Data.Charm then pcall(function() Data.Charm:Destroy() end) end
    EspObjects[Player] = nil
end
local function CreateESP(Player)
    if not Player or Player == LocalPlayer then return end
    local Char = Player.Character
    if not Char then return end
    if not Char:FindFirstChild("HumanoidRootPart") then return end
    RemoveESP(Player)
    local Data = {}
    EspObjects[Player] = Data
    -- Highlight (Charms) — stays as a 3-D Roblox instance
    if ESPConfig.Charms then
        local HL = Instance.new("Highlight")
        HL.FillColor        = ESPColors.Charms
        HL.FillTransparency = 0.7
        HL.OutlineColor     = ESPColors.Charms
        HL.Adornee          = Char
        HL.Parent           = Char
        Data.Charm = HL
    end
    -- Full or corner box, both without a black outline.
    if ESPConfig.Box then
        if ESPConfig.BoxType == "Corner" then
            Data.BoxCorners = {}
            for _ = 1, 8 do
                local line = Drawing.new("Line")
                line.Visible = false
                line.Color = ESPColors.Box
                line.Thickness = 2
                table.insert(Data.BoxCorners, line)
            end
        else
            local Box = Drawing.new("Square")
            Box.Visible   = false
            Box.Filled    = false
            Box.Color     = ESPColors.Box
            Box.Thickness = 2
            Data.Box = Box
        end
    end
    -- Name label — Drawing.Text, centered above the box
    if ESPConfig.Name then
        local Lbl = Drawing.new("Text")
        Lbl.Visible      = false
        Lbl.Text         = Player.Name
        Lbl.Color        = ESPColors.Name
        Lbl.Size         = 14
        Lbl.Center       = true
        Lbl.Outline      = true
        Lbl.OutlineColor = Color3.fromRGB(0, 0, 0)
        Lbl.Font         = Drawing.Fonts.UI
        Data.NameLabel = Lbl
    end
    -- Distance label — Drawing.Text, centered below the box
    if ESPConfig.Distance then
        local Lbl = Drawing.new("Text")
        Lbl.Visible      = false
        Lbl.Text         = ""
        Lbl.Color        = ESPColors.Distance
        Lbl.Size         = 12
        Lbl.Center       = true
        Lbl.Outline      = true
        Lbl.OutlineColor = Color3.fromRGB(0, 0, 0)
        Lbl.Font         = Drawing.Fonts.UI
        Data.DistLabel = Lbl
    end
    -- HP Bar — two Drawing squares (bg + fill), left side of the box
    if ESPConfig.HPBar then
        local Bg = Drawing.new("Square")
        Bg.Visible   = false
        Bg.Filled    = true
        Bg.Color     = Color3.fromRGB(15, 15, 20)
        Bg.Thickness = 1
        Data.HPBg = Bg
        local Fill = Drawing.new("Square")
        Fill.Visible   = false
        Fill.Filled    = true
        Fill.Color     = ESPColors.HPBar
        Fill.Thickness = 1
        Data.HPFill = Fill
    end
    local function HideAll()
        if Data.Box        then Data.Box.Visible        = false end
        if Data.BoxCorners then for _, line in ipairs(Data.BoxCorners) do line.Visible = false end end
        if Data.NameLabel  then Data.NameLabel.Visible  = false end
        if Data.DistLabel  then Data.DistLabel.Visible  = false end
        if Data.HPBg       then Data.HPBg.Visible       = false end
        if Data.HPFill     then Data.HPFill.Visible     = false end
    end
    local PAD = 2  -- pixels of padding around the bounding box
    local UpdateConn
    UpdateConn = RunService.Heartbeat:Connect(function()
        if not ScriptAlive or not EspObjects[Player] then
            if UpdateConn then UpdateConn:Disconnect() end
            RemoveESP(Player)
            return
        end
        local CChar = Player.Character
        if not CChar then HideAll(); return end
        local CRoot = CChar:FindFirstChild("HumanoidRootPart")
        if not CRoot then HideAll(); return end
        local bx, by, bw, bh = GetScreenBox(CChar)
        if not bx then HideAll(); return end
        -- Sync charm adornee and animate friend charms through the RGB spectrum.
        if Data.Charm then
            Data.Charm.Adornee = CChar
            local charmColor = IsCheatFriend(Player)
                and Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
                or ESPColors.Charms
            Data.Charm.FillColor = charmColor
            Data.Charm.OutlineColor = charmColor
        end
        local rx, ry, rw, rh = bx - PAD, by - PAD, bw + PAD*2, bh + PAD*2
        -- Box
        if Data.Box then
            Data.Box.Position = Vector2.new(rx, ry)
            Data.Box.Size     = Vector2.new(rw, rh)
            if IsCheatFriend(Player) then
                Data.Box.Color = Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
            else
                Data.Box.Color = ESPColors.Box
            end
            Data.Box.Visible  = true
        end
        -- Corner box: two short lines at each corner.
        if Data.BoxCorners then
            local color = IsCheatFriend(Player)
                and Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
                or ESPColors.Box
            local cornerW = math.max(4, rw * 0.25)
            local cornerH = math.max(4, rh * 0.25)
            local x1, y1, x2, y2 = rx, ry, rx + rw, ry + rh
            local points = {
                {Vector2.new(x1,y1), Vector2.new(x1+cornerW,y1)},
                {Vector2.new(x1,y1), Vector2.new(x1,y1+cornerH)},
                {Vector2.new(x2,y1), Vector2.new(x2-cornerW,y1)},
                {Vector2.new(x2,y1), Vector2.new(x2,y1+cornerH)},
                {Vector2.new(x1,y2), Vector2.new(x1+cornerW,y2)},
                {Vector2.new(x1,y2), Vector2.new(x1,y2-cornerH)},
                {Vector2.new(x2,y2), Vector2.new(x2-cornerW,y2)},
                {Vector2.new(x2,y2), Vector2.new(x2,y2-cornerH)},
            }
            for i, line in ipairs(Data.BoxCorners) do
                local corner = points[i]
                if corner then
                    line.From = corner[1]
                    line.To = corner[2]
                    line.Color = color
                    line.Visible = true
                else
                    line.Visible = false
                end
            end
        end
        -- Name (above box). Friends use the same animated RGB color as their box.
        if Data.NameLabel then
            Data.NameLabel.Position = Vector2.new(rx + rw * 0.5, ry - 16)
            if IsCheatFriend(Player) then
                Data.NameLabel.Color = Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
            else
                Data.NameLabel.Color = ESPColors.Name
            end
            Data.NameLabel.Visible  = true
        end
        -- Distance (below box)
        if Data.DistLabel then
            local MyR = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            local dist = MyR and math.floor((MyR.Position - CRoot.Position).Magnitude) or 0
            Data.DistLabel.Text     = dist .. " studs"
            Data.DistLabel.Position = Vector2.new(rx + rw * 0.5, ry + rh + 3)
            Data.DistLabel.Color = IsCheatFriend(Player)
                and Color3.fromHSV((os.clock() * 0.18) % 1, 1, 1)
                or ESPColors.Distance
            Data.DistLabel.Visible  = true
        end
        -- HP Bar (3-px wide, left of box, fills bottom-up)
        if Data.HPBg and Data.HPFill then
            local CHum = CChar:FindFirstChildOfClass("Humanoid")
            local barX = rx - 6
            Data.HPBg.Position = Vector2.new(barX - 1, ry - 1)
            Data.HPBg.Size     = Vector2.new(5, rh + 2)
            Data.HPBg.Visible  = true
            if CHum and CHum.MaxHealth > 0 then
                local ratio  = math.clamp(CHum.Health / CHum.MaxHealth, 0, 1)
                local fillH  = math.max(1, rh * ratio)
                Data.HPFill.Position = Vector2.new(barX, ry + rh - fillH)
                Data.HPFill.Size     = Vector2.new(3, fillH)
                Data.HPFill.Color    = Color3.fromRGB(
                    math.floor(255 * (1 - ratio)),
                    math.floor(220 * ratio),
                    30
                )
                Data.HPFill.Visible = true
            end
        end
    end)
    Data.UpdateConn = UpdateConn
end
function UpdateESP()
    for _, P in ipairs(Players:GetPlayers()) do
        if P ~= LocalPlayer then
            RemoveESP(P)
            if ESPConfig.Enabled and P.Character then task.wait(0.05); CreateESP(P) end
        end
    end
end
local function AttachESPToPlayer(P)
    -- Normal respawn
    P.CharacterAdded:Connect(function(char)
        if not ScriptAlive then return end
        char:WaitForChild("HumanoidRootPart", 10)
        task.wait(0.05)
        if not ESPConfig.Enabled then return end
        CreateESP(P)
        if ESPConfig.Skeleton then AddSkeleton(P) end
    end)
    -- StreamingEnabled: character streams back into range without firing CharacterAdded
    P:GetPropertyChangedSignal("Character"):Connect(function()
        if not ScriptAlive then return end
        local char = P.Character
        if not char then RemoveESP(P); RemoveSkeleton(P); return end
        task.spawn(function()
            char:WaitForChild("HumanoidRootPart", 10)
            task.wait(0.05)
            if not ScriptAlive or not ESPConfig.Enabled then return end
            if P.Character ~= char then return end  -- already changed again
            CreateESP(P)
            if ESPConfig.Skeleton then AddSkeleton(P) end
        end)
    end)
end
table.insert(Connections, Players.PlayerAdded:Connect(function(P)
    AttachESPToPlayer(P)
end))
table.insert(Connections, Players.PlayerRemoving:Connect(function(P)
    RemoveESP(P)
    RemoveSkeleton(P)
end))
task.spawn(function()
    task.wait(0)  -- just yield once so script finishes loading, no extra delay
    for _, P in ipairs(Players:GetPlayers()) do
        if P ~= LocalPlayer then
            if P.Character then
                CreateESP(P)
                if ESPConfig.Skeleton then AddSkeleton(P) end
            end
            AttachESPToPlayer(P)
        end
    end
end)
-- Periodic ESP reconciliation. This catches players who join or stream in
-- after ESP has already been enabled, without rebuilding existing drawings.
task.spawn(function()
    while ScriptAlive do
        task.wait(5)
        if not ScriptAlive then break end
        if ESPConfig.Enabled then
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer and player.Character then
                    local root = player.Character:FindFirstChild("HumanoidRootPart")
                    if root and not EspObjects[player] then
                        CreateESP(player)
                    end
                    if ESPConfig.Skeleton and not SkeletonObjects[player] then
                        AddSkeleton(player)
                    end
                end
            end
        end
    end
end)
-- ═══════ SPEED & JUMP — FIX: UseJumpPower = true ═══════
local function ApplySpeedAndJump()
    if not ScriptAlive then return end
    local Char = LocalPlayer.Character
    if not Char then return end
    local Hum = Char:FindFirstChildOfClass("Humanoid")
    if not Hum then return end
    if Config.SpeedEnabled then
        Hum.WalkSpeed = Config.SpeedValue
    end
    if Config.JumpEnabled then
        if not Hum.UseJumpPower then Hum.UseJumpPower = true end
        Hum.JumpPower = Config.JumpValue
    end
end
local function HookHumanoid(Hum)
    if not Hum then return end
    table.insert(Connections, Hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
        if Config.SpeedEnabled and ScriptAlive then Hum.WalkSpeed = Config.SpeedValue end
    end))
    table.insert(Connections, Hum:GetPropertyChangedSignal("JumpPower"):Connect(function()
        if Config.JumpEnabled and ScriptAlive then
            if not Hum.UseJumpPower then Hum.UseJumpPower = true end
            Hum.JumpPower = Config.JumpValue
        end
    end))
    table.insert(Connections, Hum:GetPropertyChangedSignal("UseJumpPower"):Connect(function()
        if Config.JumpEnabled and ScriptAlive and not Hum.UseJumpPower then
            Hum.UseJumpPower = true
            Hum.JumpPower = Config.JumpValue
        end
    end))
end
local function OnCharSpawn(Char)
    Character = Char
    local Hum = Char:WaitForChild("Humanoid", 10)
    if Hum then HookHumanoid(Hum); ApplySpeedAndJump() end
end
table.insert(Connections, LocalPlayer.CharacterAdded:Connect(OnCharSpawn))
do
    local Hum = Character:FindFirstChildOfClass("Humanoid")
    if Hum then HookHumanoid(Hum); ApplySpeedAndJump() end
end
table.insert(Connections, RunService.Heartbeat:Connect(function()
    if ScriptAlive then ApplySpeedAndJump() end
end))
ApplyLoadedConfig = function()
    local espMap = {
        ["Enable ESP"] = "Enabled",
        Charms = "Charms", Box = "Box", Name = "Name",
        Distance = "Distance", ["HP Bar"] = "HPBar", Skeleton = "Skeleton", ["Item ESP"] = "ItemESP",
    }
    for uiName, cfgKey in pairs(espMap) do
        local setter = ToggleSetters[uiName]
        if setter and ESPConfig[cfgKey] ~= nil then
            setter(ESPConfig[cfgKey], true)
        end
    end
    local rageMap = {
        Fly = "FlyEnabled", ["Speed Boost"] = "SpeedEnabled",
        ["Jump Power"] = "JumpEnabled", Noclip = "NoclipEnabled",
        ["Time Stop"] = "HitboxEnabled",
        Invisibility = "InvisibilityEnabled",
        ["Aim Assistant"] = "AimEnabled",
        ["Hit Sound"] = "HitSoundEnabled",
        ["Kill Sound"] = "KillSoundEnabled",
        ["Death Sound"] = "DeathSoundEnabled",
        ["Draw FOV"] = "DrawFOV",
        ["Auto Wall"] = "AutoWallEnabled",
        ["Free Cam"]  = "FreeCamEnabled",
        Fullbright = "FullbrightEnabled",
        ["No Fog"] = "NoFogEnabled",
        ["No CD Jump"] = "NoCDJumpEnabled",
        ["Instant Interaction"] = "InstantInteractionEnabled",
        ["No Void"] = "NoVoidEnabled",
        Orbit = "OrbitEnabled",
        ["Anti-Fling"] = "AntiFlingEnabled",
        Emote = "EmoteEnabled",
    }
    for uiName, cfgKey in pairs(rageMap) do
        local setter = ToggleSetters[uiName]
        if setter and Config[cfgKey] ~= nil then
            setter(Config[cfgKey], true)
        end
    end
    local sliderMap = {
        ["Fly Speed"]    = function() return Config.FlySpeed end,
        Speed            = function() return Config.SpeedValue end,
        Jump             = function() return Config.JumpValue end,
        ["Noclip Speed"] = function() return Config.NoclipSpeed end,
        ["Cam Speed"]    = function() return Config.FreeCamSpeed end,
        ["Interaction Delay"] = function() return Config.InteractionDelay end,
        FOV              = function() return Config.AimFOV end,
        Smooth           = function() return Config.AimSmooth end,
        ["Hit Sound Volume (%)"] = function() return Config.HitSoundVolume end,
        ["Kill Sound Volume (%)"] = function() return Config.KillSoundVolume end,
        ["Death Sound Volume (%)"] = function() return Config.DeathSoundVolume end,
        ["Orbit Speed"] = function() return Config.OrbitSpeed end,
        ["Orbit Distance"] = function() return Config.OrbitDistance end,
        X                = function() return Config.CoordX end,
        Y                = function() return Config.CoordY end,
        Z                = function() return Config.CoordZ end,
    }
    for _, slider in ipairs(AllSliders) do
        local getter = sliderMap[slider.Name]
        if getter then slider:SetCustomValue(getter(), true) end
    end
    for key, btn in pairs(ColorSwatchBtns) do
        if ESPColors[key] then btn.BackgroundColor3 = ESPColors[key] end
    end
    if RefreshAimPriorityUI then RefreshAimPriorityUI() end
    if RefreshFriendsUI then RefreshFriendsUI() end
    if RefreshBoxTypeUI then RefreshBoxTypeUI() end
    if RefreshItemESPOptionsUI then RefreshItemESPOptionsUI() end
    if RefreshHitSoundUI then RefreshHitSoundUI() end
    if RefreshKillSoundUI then RefreshKillSoundUI() end
    if RefreshDeathSoundUI then RefreshDeathSoundUI() end
    if RefreshOrbitTargetUI then RefreshOrbitTargetUI() end
    if RefreshEmoteUI then RefreshEmoteUI() end
    ApplyInterfaceScale(Config.InterfaceScale or 100)
    ApplyTheme(Config.Theme or "Cosmic")
    if Config.FlyEnabled then StartFly() else StopFly() end
    if Config.NoclipEnabled then StartBlink() else StopBlink() end
    if Config.HitboxEnabled then StartHitbox() else StopHitbox() end
    if Config.InvisibilityEnabled then StartInvisibility() else StopInvisibility() end
    if Config.FreeCamEnabled then StartFreeCam() else StopFreeCam() end
    if Config.AimEnabled then StartAim() else StopAim() end
    if Config.HitSoundEnabled or Config.KillSoundEnabled then StartHitSound() else StopHitSound() end
    if Config.DeathSoundEnabled then StartDeathSound() else StopDeathSound() end
    if Config.DrawFOV then StartDrawFOV() else StopDrawFOV() end
    if Config.InstantInteractionEnabled then StartInstantInteraction() else StopInstantInteraction() end
    if Config.NoVoidEnabled then StartNoVoid() else StopNoVoid() end
    if Config.OrbitEnabled then StartOrbit() else StopOrbit() end
    if Config.AntiFlingEnabled then StartAntiFling() else StopAntiFling() end
    if Config.EmoteEnabled then StartEmote() else StopEmote() end
    if Config.FullbrightEnabled then ApplyForcedLighting() else RestoreFullbright() end
    if Config.NoFogEnabled then ApplyForcedLighting() else RestoreNoFog() end
    if ESPConfig.ItemESP then StartItemESP() else StopItemESP() end
    UpdateAllSkeletons()
    UpdateESP()
    -- Remove movement effects left by the previously active config.
    local loadedHumanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if loadedHumanoid then
        if not Config.SpeedEnabled then loadedHumanoid.WalkSpeed = 16 end
        if not Config.JumpEnabled then loadedHumanoid.JumpPower = 50 end
    end
    ApplySpeedAndJump()
end
-- Apply the default theme after every interface element has been created.
ApplyTheme(Config.Theme or "Cosmic")
-- ── LOADING ANIMATION ────────────────────────────────────
local loadSteps = {
    {p = 0.15, text = "Initializing modules..."},
    {p = 0.35, text = "Loading ESP system..."},
    {p = 0.55, text = "Loading features..."},
    {p = 0.75, text = "Building interface..."},
    {p = 0.90, text = "Finalizing..."},
    {p = 1.00, text = "Ready!"},
}
task.spawn(function()
    local duration = math.random(10, 30) * 0.1  -- 1.0 – 3.0 сек
    local elapsed  = 0
    local currentStep = 1
    local conn
    conn = RunService.Heartbeat:Connect(function(dt)
        elapsed = math.min(elapsed + dt, duration)
        local pct = elapsed / duration
        LoadBar.Size = UDim2.new(pct, 0, 1, 0)
        while currentStep <= #loadSteps and pct >= loadSteps[currentStep].p do
            LoadSub.Text = loadSteps[currentStep].text
            currentStep = currentStep + 1
        end
        if elapsed >= duration then
            conn:Disconnect()
            task.wait(0.8)
            LoadFrame.Visible = false
            LoadFrame:Destroy()
            IsLoading = false
            MF.Visible = true
            UIS.MouseIconEnabled = true
            UIS.MouseBehavior = Enum.MouseBehavior.Default
            -- Autoload runs only after the loading screen has fully finished.
            task.defer(function()
                task.wait(0.05)
                if AutoloadConfigState.Enabled and AutoloadConfigState.Name ~= "" then
                    local loaded = LoadConfig(AutoloadConfigState.Name)
                    if not loaded then
                        AutoloadConfigState.Enabled = false
                        SaveAutoloadConfigState()
                        if RefreshAutoloadConfigUI then RefreshAutoloadConfigUI() end
                    end
                end
            end)
        end
    end)
end)
